// Building parts in one oblique view (depth runs up and to the right): boxes with arched windows, stairs whose treads
// and risers show, and an observatory. Fills are colourway roles; side faces are the fill darkened toward ink and
// stippled, like the triptych's shaded walls.
import { crescent, ellipse, circle, line, shape, stipple, tint } from "./motifs"
import { el, n, type Pen, type Rs } from "./svg"

export const DEPTH = [24, -15] as const
type Pt = readonly [number, number]

export const shade = (f: string, k = 84) =>
  `color-mix(in oklab, var(--${f}) ${k}%, var(--ink))`
export const tintOf = (f: string, k = 45) =>
  `color-mix(in oklab, var(--${f}) ${k}%, var(--paper))`
export const quad = (pts: readonly Pt[]) =>
  `M ${pts.map(([x, y]) => `${n(x)} ${n(y)}`).join(" L ")} Z`
export const archPath = (x: number, base: number, w: number, h: number) => {
  const r = w / 2
  const spring = Math.min(base, base - h + r)
  return `M ${n(x)} ${n(base)} V ${n(spring)} A ${n(r)} ${n(r)} 0 0 1 ${n(x + w)} ${n(spring)} V ${n(base)} Z`
}

/** A box: front face, top and right side, with a row of arched ink cavities on the front. */
export function box(
  p: Pen,
  {
    x,
    y,
    w,
    h,
    fill,
    depth = 1,
    windows = 0,
    top,
  }: {
    x: number
    y: number
    w: number
    h: number
    fill: string
    depth?: number
    windows?: number
    top?: string
  },
) {
  const [dx, dy] = [DEPTH[0] * depth, DEPTH[1] * depth]
  const side = quad([
    [x + w, y],
    [x + w + dx, y + dy],
    [x + w + dx, y + h + dy],
    [x + w, y + h],
  ])
  let out =
    shape(p, side, shade(fill)) +
    tint(side, stipple(p)) +
    shape(
      p,
      quad([
        [x, y],
        [x + dx, y + dy],
        [x + w + dx, y + dy],
        [x + w, y],
      ]),
      top ?? tintOf(fill),
    ) +
    shape(
      p,
      quad([
        [x, y],
        [x + w, y],
        [x + w, y + h],
        [x, y + h],
      ]),
      fill,
    )
  if (windows) {
    const ww = Math.min(26, w / (windows * 1.9))
    const gap = (w - windows * ww) / (windows + 1)
    const wh = Math.min(h * 0.5, ww * 2.1)
    for (let i = 0; i < windows; i++)
      out += shape(
        p,
        archPath(x + gap + i * (ww + gap), y + h * 0.22 + wh, ww, wh),
        "ink",
      )
  }
  return out
}

/** A stair rising to the left from (x0, y0) to (x1, y1): paper treads, shaded risers, a coloured stringer. */
export function steps(
  p: Pen,
  {
    x0,
    y0,
    x1,
    y1,
    count,
    fill,
    depth = 1.1,
    under = 26,
  }: {
    x0: number
    y0: number
    x1: number
    y1: number
    count: number
    fill: string
    depth?: number
    under?: number
  },
) {
  const run = (x0 - x1) / count
  const rise = (y0 - y1) / count
  const [dx, dy] = [DEPTH[0] * depth, DEPTH[1] * depth]
  let parts = ""
  let profile = `M ${n(x0)} ${n(y0 + under)} L ${n(x0)} ${n(y0)}`
  for (let k = 0, x = x0, y = y0; k < count; k++, x -= run, y -= rise) {
    parts += shape(
      p,
      quad([
        [x, y],
        [x, y - rise],
        [x + dx, y - rise + dy],
        [x + dx, y + dy],
      ]),
      shade(fill, 78),
    )
    parts += shape(
      p,
      quad([
        [x, y - rise],
        [x - run, y - rise],
        [x - run + dx, y - rise + dy],
        [x + dx, y - rise + dy],
      ]),
      "paper",
    )
    profile += ` V ${n(y - rise)} H ${n(x - run)}`
  }
  profile += ` V ${n(y1 + under)} Z`
  const shadow = `M ${n(x1)} ${n(y1 + under * 0.4)} L ${n(x0)} ${n(y0 + under * 0.4)} V ${n(y0 + under)} L ${n(x1)} ${n(y1 + under)} Z`
  return parts + shape(p, profile, fill) + tint(shadow, stipple(p))
}

/** An observatory: a drum with windows, a ribbed dome with its slit open, and a telescope looking out. */
export function observatory(
  p: Pen,
  r: Rs,
  {
    cx,
    base,
    rad,
    fill,
  }: { cx: number; base: number; rad: number; fill: string },
) {
  const drum = rad * 0.62
  let out = box(p, {
    x: cx - rad,
    y: base - drum,
    w: rad * 2,
    h: drum,
    fill,
    depth: 0.7,
    windows: 4,
  })
  const dcx = cx + DEPTH[0] * 0.35
  const dbase = base - drum + DEPTH[1] * 0.35
  const rd = rad * 0.92
  const dome = `M ${n(dcx - rd)} ${n(dbase)} A ${n(rd)} ${n(rd)} 0 0 1 ${n(dcx + rd)} ${n(dbase)} Z`
  const clip = p.uid("dome")
  const tilt = r.between(-0.9, -0.5)
  const [tx, ty] = [dcx - rd * 0.1, dbase - rd * 0.62]
  const [c, s] = [Math.cos(tilt), Math.sin(tilt)]
  const tube = (len: number, w0: number, w1: number) =>
    quad([
      [tx - s * w0, ty + c * w0],
      [tx + c * len - s * w1, ty + s * len + c * w1],
      [tx + c * len + s * w1, ty + s * len - c * w1],
      [tx + s * w0, ty - c * w0],
    ])
  out += el("clipPath", { id: clip }, el("path", { d: dome }, null))
  out += shape(p, dome, "paper")
  out += tint(crescent(dcx, dbase, rd, -rd * 0.55, -rd * 0.25), stipple(p), {
    "clip-path": `url(#${clip})`,
  })
  let ribs = ""
  for (const k of [-0.62, -0.3, 0.3, 0.62])
    ribs += `M ${n(dcx + k * rd)} ${n(dbase)} Q ${n(dcx + k * rd * 0.9)} ${n(dbase - rd * 0.85)} ${n(dcx)} ${n(dbase - rd)} `
  out += line(p, ribs, { "clip-path": `url(#${clip})` })
  out += shape(
    p,
    `M ${n(dcx - rd * 0.12)} ${n(dbase - rd * 0.99)} H ${n(dcx + rd * 0.12)} V ${n(dbase - rd * 0.2)} H ${n(dcx - rd * 0.12)} Z`,
    "ink",
  )
  out += shape(p, tube(rd * 0.95, 11, 15), "paper")
  const [mx, my] = [tx + c * rd * 0.95, ty + s * rd * 0.95]
  out += shape(p, ellipse(mx, my, 6, 14), "ink", {
    transform: `rotate(${n((tilt * 180) / Math.PI)} ${n(mx)} ${n(my)})`,
  })
  return (
    out +
    shape(
      p,
      `M ${n(dcx - 3)} ${n(dbase - rd - 26)} H ${n(dcx + 3)} V ${n(dbase - rd + 2)} H ${n(dcx - 3)} Z`,
      "paper",
    ) +
    shape(p, circle(dcx, dbase - rd - 30, 6), "paper")
  )
}

// Cloud banks and the arcade band. A bank is puffs on a flat base, outlined as one shape (every part stroked at twice
// the line, then filled on top without one) with open arcs inside where one puff overlaps another; a floating bank
// (a stratum in the sky) is cut flat and outlined at its base.
import { circle, line, paint, stipple, tint } from "./motifs"
import { el, n, type Pen, type Rs } from "./svg"

export interface Bank {
  x0: number
  x1: number
  base: number
  top: number
  rmin: number
  rmax: number
  fill: string
  contours?: number
  floating?: boolean
}

export function cloudBank(p: Pen, r: Rs, b: Bank) {
  const {
    x0,
    x1,
    base,
    top,
    rmin,
    rmax,
    fill,
    contours = 0.65,
    floating = false,
  } = b
  const puffs: { cx: number; cy: number; r: number }[] = []
  let x = x0 - rmax * 0.3
  while (x < x1 + rmax * 0.3) {
    const rad = r.between(rmin, rmax)
    puffs.push({
      cx: x,
      cy: r.between(top + rad, top + rad + (rmax - rmin) * 0.8),
      r: rad,
    })
    x += rad * r.between(1.05, 1.45)
  }
  if (floating)
    for (const q of puffs) {
      q.cx = Math.min(Math.max(q.cx, x0 + q.r * 0.6), x1 - q.r * 0.6)
      q.cy = Math.min(q.cy, base - q.r * 0.3)
    }
  const shelf = Math.min(
    puffs.reduce((s, q) => s + q.cy, 0) / puffs.length,
    base - 4,
  )
  const [left, right] = floating ? [x0, x1] : [x0 - rmax, x1 + rmax]
  const parts =
    puffs.map((q) => circle(q.cx, q.cy, q.r)).join(" ") +
    ` M ${n(left)} ${n(shelf)} H ${n(right)} V ${n(floating ? base : base + 40)} H ${n(left)} Z`
  let arcs = ""
  puffs.forEach((q, i) => {
    if (i === 0 || !r.chance(contours)) return
    const a0 = (r.between(192, 205) * Math.PI) / 180
    const a1 = (r.between(238, 262) * Math.PI) / 180
    const pt = (a: number) =>
      `${n(q.cx + Math.cos(a) * q.r)} ${n(q.cy + Math.sin(a) * q.r)}`
    arcs += `M ${pt(a0)} A ${n(q.r)} ${n(q.r)} 0 0 1 ${pt(a1)} `
  })
  const clip = p.uid("cloud")
  let defs = el("clipPath", { id: clip }, el("path", { d: parts }, null))
  let cutInk = {}
  let cutFill = {}
  if (floating) {
    const [ci, cf] = [p.uid("ci"), p.uid("cf")]
    const box = (y: number) =>
      el(
        "rect",
        {
          x: left - rmax * 2,
          y: top - rmax,
          width: right - left + rmax * 4,
          height: y - top + rmax,
        },
        null,
      )
    defs +=
      el("clipPath", { id: ci }, box(base + p.L * 1.2)) +
      el("clipPath", { id: cf }, box(base))
    cutInk = { "clip-path": `url(#${ci})` }
    cutFill = { "clip-path": `url(#${cf})` }
  }
  return (
    defs +
    el(
      "path",
      {
        d: parts,
        style: "fill:var(--ink);stroke:var(--ink)",
        "stroke-width": p.L * 2,
        "vector-effect": "non-scaling-stroke",
        ...cutInk,
      },
      null,
    ) +
    tint(parts, paint(fill), cutFill) +
    (arcs
      ? el("g", cutFill, line(p, arcs, { "clip-path": `url(#${clip})` }))
      : "")
  )
}

/**
 * The arcade band between sections: a wall in `fill` whose arched openings show the section below, each opening
 * revealing the wall's thickness, stippled, along its right side.
 */
export function arcadeBand(
  p: Pen,
  {
    width = 1200,
    height = 104,
    bay = 124,
    pier = 34,
    rise = 62,
    depth = 10,
    fill = "cloud",
  } = {},
) {
  const r = (bay - pier) / 2
  const foot = height - 2
  const spring = foot - rise + r
  const arch = (a: number, c: number) =>
    `M ${n(a)} ${n(foot)} V ${n(spring)} A ${n(r)} ${n(r)} 0 0 1 ${n(c)} ${n(spring)} V ${n(foot)}`
  let holes = ""
  let inner = ""
  let edges = ""
  for (let x = -bay; x < width + bay; x += bay) {
    const [a, c] = [x + pier / 2, x + bay - pier / 2]
    holes += `${arch(a, c)} Z `
    inner += `${arch(a - depth, c - depth)} Z `
    edges += `${arch(a, c)} M ${n(c)} ${n(foot)} H ${n(c + pier)} `
  }
  const big = `M ${-bay} 0 H ${width + bay} V ${n(foot)} H ${-bay} Z`
  const clip = p.uid("arches")
  const reveal = { "fill-rule": "evenodd", "clip-path": `url(#${clip})` }
  return (
    el("clipPath", { id: clip }, el("path", { d: holes }, null)) +
    tint(`${big} ${holes}`, fill, { "fill-rule": "evenodd" }) +
    tint(`${big} ${inner}`, fill, reveal) +
    tint(`${big} ${inner}`, stipple(p), reveal) +
    line(p, inner, { "clip-path": `url(#${clip})` }) +
    line(p, edges, { "stroke-linecap": "square" })
  )
}

// Scenes composed from the object library: a procession of objects in an arcade's niches, a skyline of objects on a
// cloud bank (the observatory and the stage are in compositions-more.ts). Each picks its objects from a pool by seed and skips
// any name the library does not have, so a scene never breaks while the library grows.
import { box } from "./buildings"
import { cloudBank } from "./clouds"
import { line, scatter, shape, stipple, tint } from "./motifs"
import { OBJECTS, put, type Thing } from "./objects"
import type { Scene } from "./scene"
import { n, rs, type Rs } from "./svg"

/** `count` different objects from `pool`, in a seeded order, skipping names the library lacks. */
function pick(r: Rs, pool: readonly string[], count: number): Thing[] {
  const have = pool.map((name) => OBJECTS[name]).filter((t): t is Thing => !!t)
  const out: Thing[] = []
  const left = [...have]
  while (out.length < count && left.length > 0)
    out.push(left.splice(Math.floor(r.next() * left.length), 1)[0] as Thing)
  return out
}

/** The height that fits a thing inside a box of w × h. */
const fit = (t: Thing, w: number, h: number) => Math.min(h, (w * t.h) / t.w)

const NICHE = [
  "globe",
  "hourglass",
  "lantern",
  "armillary-sphere",
  "telescope",
  "urn",
  "topiary",
  "orange-tree",
  "cactus",
  "column",
  "obelisk",
  "sundial",
  "microphone",
  "bell",
  "allium",
] as const

/** A procession: a long arcade whose lit niches each hold a different object, standing on one floor, clouds below. */
export const procession: Scene = {
  w: 1600,
  h: 440,
  fit: "xMidYMax slice",
  body: (p, seed) => {
    const r = rs(seed, "procession")
    const [bay, pier, top, floor] = [228, 54, 64, 372]
    const count = Math.ceil(1600 / bay) + 1
    const things = pick(r, NICHE, count)
    const wall = r.pick(["tone-4", "structure", "tone-1"])
    const lit = ["sun", "highlight", "plane-2", "tone-2"].filter(
      (f) => f !== wall,
    )
    let niches = ""
    for (let i = 0; i < count; i++) {
      const x = -60 + i * bay + pier / 2
      const w = bay - pier
      const rad = w / 2
      const d = `M ${n(x)} ${n(floor)} V ${n(top + 70 + rad)} A ${n(rad)} ${n(rad)} 0 0 1 ${n(x + w)} ${n(top + 70 + rad)} V ${n(floor)} Z`
      const back = lit[i % lit.length] as string
      niches +=
        shape(p, d, back) +
        tint(
          `M ${n(x + w - 14)} ${n(floor)} V ${n(top + 70 + rad)} H ${n(x + w)} V ${n(floor)} Z`,
          stipple(p),
        )
      const t = things[i % Math.max(1, things.length)]
      if (t) {
        const h = fit(t, w - 26, floor - top - 96)
        const tw = (t.w * h) / t.h
        niches += put(p, seed, t, {
          x: x + (w - tw) / 2,
          y: floor - 4,
          h,
          key: `n${i}`,
        })
      }
    }
    return (
      box(p, {
        x: -80,
        y: top,
        w: 1760,
        h: floor - top,
        fill: wall,
        depth: 1,
      }) +
      niches +
      line(p, `M -80 ${n(top + 30)} H 1680`) +
      line(p, `M -80 ${n(floor)} H 1680`) +
      cloudBank(p, rs(seed, "procession-clouds"), {
        x0: -40,
        x1: 1640,
        base: 452,
        top: 392,
        rmin: 20,
        rmax: 34,
        fill: "cloud",
      })
    )
  },
}

const TALL = [
  "lighthouse",
  "spiral-stair",
  "obelisk",
  "cypress",
  "palm",
  "column",
  "great-telescope",
  "advertising-column",
] as const
const SHORT = [
  "globe",
  "hourglass",
  "urn",
  "fountain",
  "gate",
  "cactus",
  "topiary",
  "speaker-stack",
  "sundial",
  "orange-tree",
  "hedge-arch",
  "suitcase",
] as const

/** A skyline: tall and short objects alternating on a cloud bank, a sun or a planet behind, the sky's marks above. */
export const skyline: Scene = {
  w: 1600,
  h: 520,
  fit: "xMidYMax slice",
  body: (p, seed) => {
    const r = rs(seed, "skyline")
    const tall = pick(r, TALL, 5)
    const short = pick(r, SHORT, 5)
    const row: { t: Thing; h: number }[] = []
    for (let i = 0; i < 10; i++) {
      const t = (i % 2 ? short : tall)[Math.floor(i / 2)]
      if (t)
        row.push({ t, h: i % 2 ? r.between(170, 240) : r.between(330, 420) })
    }
    const widths = row.map(({ t, h }) => (t.w * h) / t.h)
    const gap = Math.max(
      10,
      (1640 - widths.reduce((a, b) => a + b, 0)) / Math.max(1, row.length - 1),
    )
    let x = -20
    let things = ""
    row.forEach(({ t, h }, i) => {
      things += put(p, seed, t, {
        x,
        y: 470,
        h,
        key: `s${i}`,
        flip: r.chance(0.3),
      })
      x += (widths[i] ?? 0) + gap
    })
    const sky = OBJECTS["ringed-planet"] ?? OBJECTS["sun-rays"]
    return (
      (sky
        ? put(p, seed, sky, {
            x: r.between(560, 900),
            y: 230,
            h: 170,
            key: "sky",
          })
        : "") +
      scatter(p, rs(seed, "skyline-sky"), {
        x0: 40,
        y0: 20,
        x1: 1560,
        y1: 160,
        sparkles: 6,
        rings: 4,
        dots: 8,
      }) +
      things +
      cloudBank(p, rs(seed, "skyline-clouds"), {
        x0: -40,
        x1: 1640,
        base: 540,
        top: 450,
        rmin: 22,
        rmax: 38,
        fill: "cloud",
      })
    )
  },
}

// The smaller formats: a window for arch-topped card images, a medallion, the band between sections, the arcade wall
// at a section's head and the doorway of an empty state.
import { box, DEPTH, observatory } from "./buildings"
import { pinwheelArch, plant } from "./plants"
import { arcadeBand, cloudBank } from "./clouds"
import { oneOf, put } from "./objects"
import { circle, pinwheel, scatter, shape } from "./motifs"
import { platform } from "./parts"
import { el, rs } from "./svg"
import type { Scene } from "./scene"

/** A window: a platform and dome above clouds under a pinwheel sun, for an arch-topped card image. */
export const windowScene: Scene = {
  w: 300,
  h: 320,
  fit: "xMidYMax slice",
  body: (p, seed) => {
    const [W, ground] = [300, 360]
    const r = (k: string) => rs(seed, k)
    const sun = r("sun")
    return (
      pinwheel(
        p,
        sun.between(200, 240),
        sun.between(70, 96),
        sun.between(30, 38),
        "sun",
        { turn: sun.next() * 6 },
      ) +
      scatter(p, r("sky"), {
        x0: 20,
        y0: 20,
        x1: 180,
        y1: 120,
        sparkles: 2,
        rings: 2,
        dots: 3,
        size: [6, 10],
      }) +
      cloudBank(p, r("back"), {
        x0: 0,
        x1: W,
        base: ground,
        top: 170,
        rmin: 26,
        rmax: 44,
        fill: "paper",
      }) +
      platform(p, r("platform"), {
        cx: r("px").between(120, 170),
        cy: 180,
        rx: 78,
        ground,
        dome: true,
      }) +
      cloudBank(p, r("front"), {
        x0: 0,
        x1: W,
        base: ground,
        top: 236,
        rmin: 22,
        rmax: 38,
        fill: "cloud",
      })
    )
  },
}

/** A medallion: a pinwheel, or a pinwheel seen through an arch on clouds, in a round frame (avatars, featured figures). */
export const medallion: Scene = {
  w: 120,
  h: 120,
  fit: "xMidYMid meet",
  body: (p, seed) => {
    const r = rs(seed, "medallion")
    const clip = p.uid("medal")
    const ring = circle(60, 60, 54)
    const inner = r.chance(0.5)
      ? pinwheel(p, 60, 60, 70, r.pick(["sun", "bloom", "structure"]), {
          turn: r.next() * 6,
          ring: false,
        })
      : shape(p, "M 0 0 H 120 V 120 H 0 Z", "canvas") +
        pinwheelArch(p, {
          x: r.between(30, 36),
          base: 104,
          w: 52,
          h: 74,
          frame: r.pick(["structure", "bloom", "platform"]),
          colour: "sun",
        }) +
        cloudBank(p, rs(seed, "medal-cloud"), {
          x0: 0,
          x1: 120,
          base: 140,
          top: 92,
          rmin: 10,
          rmax: 16,
          fill: "cloud",
        })
    return (
      el("clipPath", { id: clip }, el("path", { d: ring }, null)) +
      el("g", { "clip-path": `url(#${clip})` }, inner) +
      shape(p, ring, "none")
    )
  },
}

/** The band between sections: a cloud bank with a building rising behind it and a plant in front. */
const BAND_STANDING = [
  "lighthouse",
  "obelisk",
  "cypress",
  "palm",
  "fountain",
  "urn",
  "spiral-stair",
  "topiary",
  "column",
  "advertising-column",
  "orange-tree",
  "gate",
]
const BAND_FLYING = [
  "hot-air-balloon",
  "kite",
  "zeppelin",
  "ringed-planet",
  "comet",
  "paper-plane",
  "crescent-moon",
]

export const band: Scene = {
  w: 3200,
  h: 210,
  fit: "xMidYMax slice",
  body: (p, seed) => {
    const [w, h] = [3200, 210]
    const r = (k: string) => rs(seed, k)
    const s = h / 200
    const ax = w / 2 + r("x").between(80, 360)
    const kind = r("kind").pick(["observatory", "arch", "tower"])
    let art = cloudBank(p, r("back"), {
      x0: w / 2 - 200,
      x1: w,
      base: h,
      top: h * 0.36,
      rmin: h * 0.1,
      rmax: h * 0.18,
      fill: "paper",
    })
    if (kind === "observatory") {
      art += box(p, {
        x: ax,
        y: h * 0.5,
        w: 150 * s,
        h,
        fill: "tone-1",
        windows: 3,
      })
      art += observatory(p, r("obs"), {
        cx: ax + 75 * s,
        base: h * 0.5 + DEPTH[1] * 0.5,
        rad: 62 * s,
        fill: "plane-2",
      })
    } else if (kind === "arch") {
      art += box(p, {
        x: ax + 150 * s,
        y: h * 0.34,
        w: 80 * s,
        h,
        fill: "tone-2",
        windows: 1,
      })
      art += box(p, { x: ax, y: h * 0.1, w: 140 * s, h, fill: "tone-3" })
      art += pinwheelArch(p, {
        x: ax + 24 * s,
        base: h * 0.7,
        w: 92 * s,
        h: h * 0.52,
        frame: "leaf",
        colour: "bloom",
      })
    } else {
      art += box(p, {
        x: ax + 92 * s,
        y: h * 0.3,
        w: 80 * s,
        h,
        fill: "tone-2",
        windows: 1,
      })
      art += box(p, {
        x: ax,
        y: h * 0.08,
        w: 96 * s,
        h,
        fill: "tone-4",
        windows: 2,
      })
    }
    art += cloudBank(p, r("clouds"), {
      x0: 0,
      x1: w,
      base: h,
      top: h * 0.56,
      rmin: h * 0.11,
      rmax: h * 0.2,
      fill: "cloud",
    })
    art += plant(p, r("plant"), {
      x: w / 2 - r("plant-x").between(260, 520),
      ground: h - 8,
      height: h * 0.95,
      blooms: 2,
    })
    // Two things from the library, so every page's band has its own: one standing in the clouds, one in the sky.
    const stand = oneOf(r("stand"), BAND_STANDING)
    const fly = oneOf(r("fly"), BAND_FLYING)
    if (stand)
      art += put(p, seed, stand, {
        x: ax - r("stand-x").between(260, 420),
        y: h - 14,
        h: Math.min(h * 0.9, (150 * stand.h) / stand.w),
        key: "band",
      })
    if (fly)
      art += put(p, seed, fly, {
        x: w / 2 - r("fly-x").between(560, 760),
        y: h * 0.62,
        h: Math.min(h * 0.55, (170 * fly.h) / fly.w),
        key: "band-sky",
      })
    return (
      art +
      scatter(p, r("sky"), {
        x0: w / 2 - 240,
        y0: h * 0.08,
        x1: w / 2 + 60,
        y1: h * 0.45,
        sparkles: 3,
        rings: 2,
        dots: 4,
        size: [6, 11],
      })
    )
  },
}

