// Follies: seeded surreal architecture in the triptych's manner, drawn as SVG strings from a seed. Every fill is a
// colourway role, so a drawing reprints in every colourway; the same seed draws the same SVG on the server, in the
// browser and in every build. Framework-free: no React, no DOM, no Math.random().
import { MOTIFS, type Motif } from "./marks"
import type { Scene } from "./scene"
import { defs, pitchOf, seedNumber, TEMPLATES, type Template } from "./scenes"
import { el, pen } from "./svg"
import { thing, type Fills } from "./objects"
import { streams } from "./objects/library"

export { TEMPLATES, type Template } from "./scenes"
export { MOTIFS, type Motif } from "./marks"
export { seedOf, prng, fork, stream } from "./seed"
export { OBJECTS, COLLECTIONS, put, thing, type Thing } from "./objects"

interface Drawn {
  /** Any string or number; the same seed always draws the same folly. */
  seed?: string | number
  /** The line in CSS pixels (non-scaling, so it holds at any size). */
  line?: number
  /** An accessible name; without one the drawing is decorative and hidden from assistive technology. */
  label?: string
}

export interface FollyOptions extends Drawn {
  /** Which drawing: the city, a window, a medallion, a band, the arcade wall or the doorway. */
  template?: Template
}

export interface MotifOptions extends Drawn {
  /** Which motif: a pinwheel, a sparkle, a cloud or an archway. */
  kind?: Motif
}

/** One scene as an SVG string, sized by its container (width and height 100%). */
function draw(
  scene: Scene,
  name: string,
  data: Record<string, string>,
  pitch: number,
  { seed = "serigraph", line = 1.5, label }: Drawn,
) {
  const p = pen(String(seed), name, line)
  const body = defs(p, pitch) + scene.body(p, seedNumber(seed))
  const a11y = label
    ? { role: "img", "aria-label": label.replace(/[<>&"]/g, "") }
    : { "aria-hidden": "true" }
  return el(
    "svg",
    {
      xmlns: "http://www.w3.org/2000/svg",
      viewBox: `0 0 ${scene.w} ${scene.h}`,
      preserveAspectRatio: scene.fit,
      width: "100%",
      height: "100%",
      focusable: "false",
      ...data,
      ...a11y,
    },
    body,
  )
}

/** A folly as an SVG string, sized by its container (width and height 100%). */
export const folly = ({ template = "city", ...options }: FollyOptions = {}) =>
  draw(
    TEMPLATES[template],
    template,
    { "data-folly": template },
    pitchOf(template),
    options,
  )

/** A motif on its own as an SVG string, sized by its container; it keeps its proportions inside the box. */
export const motif = ({ kind = "sparkle", ...options }: MotifOptions = {}) =>
  draw(MOTIFS[kind], `motif-${kind}`, { "data-motif": kind }, 2.6, options)

export interface DrawingOptions extends Drawn {
  /** The object's name in the library: "spiral-stair", "telescope" … */
  object: string
  /** Role overrides by the object's part names. */
  fills?: Fills
  /** Where it stands across a box wider than it: at the start, the middle (the default) or the end. */
  align?: "start" | "middle" | "end"
}

/** One object from the library as an SVG string, sized by its container; it keeps its proportions, standing on the
 * box's foot. */
export function drawing({
  object,
  fills = {},
  align = "middle",
  ...options
}: DrawingOptions) {
  const t = thing(object)
  const x = { start: "xMin", middle: "xMid", end: "xMax" }[align]
  const scene: Scene = {
    w: t.w,
    h: t.h,
    fit: `${x}YMax meet`,
    body: (p, seed) => t.draw(p, streams(seed, `${t.name}:`), fills),
  }
  return draw(
    scene,
    `object-${object}`,
    { "data-drawing": object },
    2.6,
    options,
  )
}

// The motifs on their own, for places a whole folly is too much: a pinwheel (medallions, a spinner), a sparkle ("new",
// success, empty space), a cloud (under a heading, behind a dialog's art) and an archway (image frames, empty
// states). Each is a Scene like the templates, so motif() frames it the same way. A motif's colour is its role, or
// --motif where the page sets one.
import { archPath } from "./buildings"
import {
  circle,
  line,
  pinpoint,
  pinwheel,
  ring,
  shape,
  sparkle,
  tint,
} from "./motifs"
import { el, n, rs } from "./svg"
import type { Scene } from "./scene"

const colour = (role: string) => `var(--motif, var(--${role}))`

/** Twelve curved wedges of paper and one colour in a fine ring; the seed sets the twist and the turn. */
const pinwheelMark: Scene = {
  w: 100,
  h: 100,
  fit: "xMidYMid meet",
  body: (p, seed) => {
    const r = rs(seed, "pinwheel")
    return pinwheel(p, 50, 50, 47, colour("sun"), {
      twist: r.between(0.45, 0.8),
      turn: r.next() * 6,
    })
  },
}

/** A four-point sparkle with a small one, a ring and a pinpoint placed by the seed. */
const sparkleMark: Scene = {
  w: 100,
  h: 100,
  fit: "xMidYMid meet",
  body: (p, seed) => {
    const r = rs(seed, "sparkle")
    const [x, y] = [r.between(70, 82), r.between(16, 26)]
    return (
      sparkle(p, 42, 58, 36) +
      sparkle(p, x, y, r.between(9, 13)) +
      ring(p, r.between(80, 88), r.between(64, 78), 3.4) +
      pinpoint(r.between(12, 22), r.between(14, 26), 1.8)
    )
  },
}

/**
 * A cumulus: puffs rising to a crown and curving down to a flat base, outlined as one shape (stroked at twice the
 * line, then filled on top), with open arcs where one puff overlaps the next.
 */
const cloudMark: Scene = {
  w: 240,
  h: 96,
  fit: "xMidYMax meet",
  body: (p, seed) => {
    const r = rs(seed, "cloud")
    const base = 92
    const count = r.int(4, 6)
    const puffs = Array.from({ length: count }, (_, i) => {
      const t = i / (count - 1)
      const rad = (22 + 26 * Math.sin(Math.PI * t)) * r.between(0.88, 1.08)
      return { cx: 0, cy: base - rad, r: rad, t }
    })
    const first = puffs[0]!
    const last = puffs[count - 1]!
    // Spread the puffs so the outer ones touch the box's sides; the inner ones shift a little.
    const span = 232 - first.r - last.r
    for (const q of puffs) {
      const shift = q === first || q === last ? 0 : r.between(-0.04, 0.04)
      q.cx = 4 + first.r + span * (q.t + shift)
    }
    const shelf = base - Math.min(first.r, last.r)
    const d =
      puffs.map((q) => circle(q.cx, q.cy, q.r)).join(" ") +
      ` M ${n(first.cx)} ${n(shelf)} H ${n(last.cx)} V ${n(base)} H ${n(first.cx)} Z`
    let arcs = ""
    for (const q of puffs.slice(1, -1)) {
      if (!r.chance(0.7)) continue
      const a0 = (r.between(195, 205) * Math.PI) / 180
      const a1 = (r.between(238, 255) * Math.PI) / 180
      const pt = (a: number) =>
        `${n(q.cx + Math.cos(a) * q.r)} ${n(q.cy + Math.sin(a) * q.r)}`
      arcs += `M ${pt(a0)} A ${n(q.r)} ${n(q.r)} 0 0 1 ${pt(a1)} `
    }
    const clip = p.uid("cloud")
    return (
      el("clipPath", { id: clip }, el("path", { d }, null)) +
      el(
        "path",
        {
          d,
          style: "fill:var(--ink);stroke:var(--ink)",
          "stroke-width": p.L * 2,
          "vector-effect": "non-scaling-stroke",
        },
        null,
      ) +
      tint(d, colour("cloud")) +
      (arcs ? line(p, arcs, { "clip-path": `url(#${clip})` }) : "")
    )
  },
}

/** A round-topped opening in a thick frame with a solid ink doorway and a sill. */
const archwayMark: Scene = {
  w: 100,
  h: 124,
  fit: "xMidYMax meet",
  body: (p, seed) => {
    const r = rs(seed, "archway")
    const [w, t] = [r.between(72, 84), r.between(12, 17)]
    const x = (100 - w) / 2
    const base = 116
    const outer = archPath(x, base, w, 108)
    const inner = archPath(x + t, base, w - 2 * t, 108 - t)
    return (
      shape(p, `${outer} ${inner}`, colour("structure"), {
        "fill-rule": "evenodd",
      }) +
      shape(p, inner, "ink") +
      line(p, `M 4 ${base} H 96`)
    )
  },
}

export const MOTIFS = {
  pinwheel: pinwheelMark,
  sparkle: sparkleMark,
  cloud: cloudMark,
  archway: archwayMark,
} as const
export type Motif = keyof typeof MOTIFS

// The style's motifs as SVG fragments: inked shapes, stipple, louvers, pinwheels, sparkles and cloud banks. Fills are
// colourway roles (--structure, --cloud …) or paints; lines are non-scaling, so one line weight serves every size.
import { el, n, type Pen, type Rs } from "./svg"

const TAU = Math.PI * 2

/** A role name ('coral', 'cloud'), any CSS paint ('url(#…)', 'color-mix(…)'), or 'none'. */
export const paint = (f: string) =>
  f === "none" ? "none" : f.includes("(") ? f : `var(--${f})`

type Extra = Record<string, string | number | undefined>

/** A filled shape outlined in ink. */
export const shape = (p: Pen, d: string, fill: string, more: Extra = {}) =>
  el(
    "path",
    {
      d,
      style: `fill:${paint(fill)};stroke:var(--ink)`,
      "stroke-width": p.L,
      "stroke-linejoin": "round",
      "vector-effect": "non-scaling-stroke",
      ...more,
    },
    null,
  )
/** An open ink line. */
export const line = (p: Pen, d: string, more: Extra = {}) =>
  el(
    "path",
    {
      d,
      style: "fill:none;stroke:var(--ink)",
      "stroke-width": p.L,
      "stroke-linecap": "round",
      "vector-effect": "non-scaling-stroke",
      ...more,
    },
    null,
  )
/** A filled shape with no outline (stipple and louver overlays). */
export const tint = (d: string, fill: string, more: Extra = {}) =>
  el("path", { d, style: `fill:${paint(fill)}`, ...more }, null)

export const circle = (cx: number, cy: number, r: number) =>
  `M ${n(cx - r)} ${n(cy)} A ${n(r)} ${n(r)} 0 1 1 ${n(cx + r)} ${n(cy)} A ${n(r)} ${n(r)} 0 1 1 ${n(cx - r)} ${n(cy)} Z`
export const ellipse = (cx: number, cy: number, rx: number, ry: number) =>
  `M ${n(cx - rx)} ${n(cy)} A ${n(rx)} ${n(ry)} 0 1 1 ${n(cx + rx)} ${n(cy)} A ${n(rx)} ${n(ry)} 0 1 1 ${n(cx - rx)} ${n(cy)} Z`

/** The drawing's patterns: a staggered stipple `pitch` units apart, and horizontal louvers in the stair colour. */
export function defs(p: Pen, pitch = 3, period = 10) {
  const dotR = (0.55 * pitch) / 3
  const stipple = el(
    "pattern",
    {
      id: `${p.id}-stipple`,
      width: pitch,
      height: pitch,
      patternUnits: "userSpaceOnUse",
    },
    el(
      "circle",
      { cx: pitch / 4, cy: pitch / 4, r: dotR, style: "fill:var(--ink)" },
      null,
    ) +
      el(
        "circle",
        {
          cx: (3 * pitch) / 4,
          cy: (3 * pitch) / 4,
          r: dotR,
          style: "fill:var(--ink)",
        },
        null,
      ),
  )
  const louvers = el(
    "pattern",
    {
      id: `${p.id}-louvers`,
      width: 8,
      height: period,
      patternUnits: "userSpaceOnUse",
    },
    el("rect", { width: 8, height: period, style: "fill:var(--stair)" }, null) +
      el(
        "rect",
        {
          y: period * 0.32,
          width: 8,
          height: period * 0.68,
          style: "fill:var(--ink)",
        },
        null,
      ),
  )
  return el("defs", {}, stipple + louvers)
}
export const stipple = (p: Pen) => `url(#${p.id}-stipple)`
export const louvers = (p: Pen) => `url(#${p.id}-louvers)`

/** The part of circle (cx, cy, r) left uncovered by the same circle moved by (ox, oy): the shadow side. */
export function crescent(
  cx: number,
  cy: number,
  r: number,
  ox: number,
  oy: number,
) {
  const d = Math.hypot(ox, oy)
  const hh = Math.sqrt(r * r - (d * d) / 4)
  const [mx, my] = [cx + ox / 2, cy + oy / 2]
  const [ux, uy] = [-oy / d, ox / d]
  const p1 = [mx + ux * hh, my + uy * hh] as const
  const p2 = [mx - ux * hh, my - uy * hh] as const
  return `M ${n(p1[0])} ${n(p1[1])} A ${n(r)} ${n(r)} 0 1 1 ${n(p2[0])} ${n(p2[1])} A ${n(r)} ${n(r)} 0 0 0 ${n(p1[0])} ${n(p1[1])} Z`
}

/** A round form in a fill, stippled on its lower right. */
export const ball = (p: Pen, cx: number, cy: number, r: number, fill: string) =>
  tint(circle(cx, cy, r), fill) +
  tint(crescent(cx, cy, r, -r * 0.42, -r * 0.34), stipple(p)) +
  shape(p, circle(cx, cy, r), "none")

/** A pinwheel: curved wedges of paper and `colour` in an ink ring. */
export function pinwheel(
  p: Pen,
  cx: number,
  cy: number,
  r: number,
  colour: string,
  { count = 12, twist = 0.6, turn = 0, ring = true } = {},
) {
  let wedges = ""
  const pt = (a: number, rr: number) =>
    `${n(cx + Math.cos(a) * rr)} ${n(cy + Math.sin(a) * rr)}`
  for (let i = 0; i < count; i++) {
    const a0 = turn + (i * TAU) / count
    const a1 = a0 + TAU / count
    const d = `M ${n(cx)} ${n(cy)} Q ${pt(a0 - twist, r * 0.55)} ${pt(a0, r)} A ${n(r)} ${n(r)} 0 0 1 ${pt(a1, r)} Q ${pt(a1 - twist, r * 0.55)} ${n(cx)} ${n(cy)} Z`
    wedges += tint(d, i % 2 ? "paper" : colour)
  }
  return el(
    "g",
    { class: "pinwheel" },
    wedges + (ring ? shape(p, circle(cx, cy, r), "none") : ""),
  )
}

/** Loose marks in the sky take the surface's text colour: ink on bright canvases, paper on Night's, like stars. */
const LOOSE = "var(--text, var(--ink))"

/** A hollow ring, loose in the sky. */
export const ring = (p: Pen, cx: number, cy: number, r: number) =>
  line(p, circle(cx, cy, r), { style: `fill:none;stroke:${LOOSE}` })

/** A pinpoint dot, loose in the sky. */
export const pinpoint = (cx: number, cy: number, r: number) =>
  tint(circle(cx, cy, r), LOOSE)

/** A four-point concave sparkle, paper inside a fine ink line. */
export function sparkle(p: Pen, x: number, y: number, s: number) {
  const k = s * 0.13
  const d =
    `M ${n(x)} ${n(y - s)} Q ${n(x + k)} ${n(y - k)} ${n(x + s)} ${n(y)} Q ${n(x + k)} ${n(y + k)} ${n(x)} ${n(y + s)} ` +
    `Q ${n(x - k)} ${n(y + k)} ${n(x - s)} ${n(y)} Q ${n(x - k)} ${n(y - k)} ${n(x)} ${n(y - s)} Z`
  return shape(p, d, "paper")
}

/** Sparkles, hollow rings and pinpoint dots scattered in a box. */
export function scatter(
  p: Pen,
  r: Rs,
  {
    x0,
    y0,
    x1,
    y1,
    sparkles = 5,
    rings = 4,
    dots = 6,
    size = [8, 15],
  }: {
    x0: number
    y0: number
    x1: number
    y1: number
    sparkles?: number
    rings?: number
    dots?: number
    size?: [number, number]
  },
) {
  let out = ""
  for (let i = 0; i < sparkles; i++)
    out += sparkle(
      p,
      r.between(x0, x1),
      r.between(y0, y1),
      r.between(size[0], size[1]),
    )
  for (let i = 0; i < rings; i++)
    out += ring(p, r.between(x0, x1), r.between(y0, y1), r.between(2.5, 4.5))
  for (let i = 0; i < dots; i++)
    out += pinpoint(r.between(x0, x1), r.between(y0, y1), 1.6)
  return out
}

// Architecture, continued: a lighthouse, a gateway and a bridge.
import { archPath, box, quad, tintOf } from "../buildings"
import { circle, line, shape, sparkle, stipple, tint } from "../motifs"
import { cone, dome, slab } from "./forms"
import { fillOf, type Thing } from "./library"

/** A lighthouse: a striped tapering tower, a gallery, the lantern room and its dome, and two beams. */
const lighthouse: Thing = {
  name: "lighthouse",
  title: "a lighthouse",
  collection: "architecture",
  w: 260,
  h: 420,
  draw: (p, r, fills) => {
    const [cx, foot, top] = [130, 408, 150]
    const [wb, wt] = [46, 30]
    const body = fillOf(fills, "tower", "paper")
    const band = fillOf(fills, "band", "structure")
    const edge = (y: number) => wb + ((wt - wb) * (foot - y)) / (foot - top)
    const tower = quad([
      [cx - wb, foot],
      [cx - wt, top],
      [cx + wt, top],
      [cx + wb, foot],
    ])
    const clip = p.uid("tower")
    const bands = [0, 1, 2]
      .map((i) => {
        const y0 = foot - 40 - i * 82
        const y1 = y0 - 40
        return tint(
          quad([
            [cx - edge(y0) - 2, y0],
            [cx - edge(y1) - 2, y1],
            [cx + edge(y1) + 2, y1],
            [cx + edge(y0) + 2, y0],
          ]),
          band,
        )
      })
      .join("")
    const shadowSide = quad([
      [cx + wb * 0.35, foot],
      [cx + wt * 0.35, top],
      [cx + wt, top],
      [cx + wb, foot],
    ])
    const beams = r("beams").chance(0.7)
      ? tint(`M ${cx} 104 L 0 70 L 0 132 Z`, tintOf("sun", 40)) +
        tint(`M ${cx} 104 L 260 64 L 260 128 Z`, tintOf("sun", 40))
      : ""
    return (
      beams +
      `<clipPath id="${clip}"><path d="${tower}"/></clipPath>` +
      shape(p, tower, body) +
      `<g clip-path="url(#${clip})">${bands}${tint(shadowSide, stipple(p))}</g>` +
      shape(p, tower, "none") +
      shape(p, archPath(cx - 9, foot, 18, 34), "ink") +
      shape(p, archPath(cx - 6, foot - 150, 12, 22), "ink") +
      slab(p, {
        cx,
        y: top - 8,
        rx: 46,
        thick: 8,
        fill: fillOf(fills, "gallery", "platform"),
      }) +
      box(p, {
        x: cx - 24,
        y: 92,
        w: 48,
        h: 40,
        fill: fillOf(fills, "lantern", "sun"),
        depth: 0.5,
        windows: 2,
      }) +
      dome(p, { cx: cx + 6, base: 88, r: 26, fill: band }) +
      shape(p, circle(cx + 6, 58, 4), "ink")
    )
  },
}

