// The solid forms objects are built from, in the follies' one oblique view and one light (from the upper left): flat
// fills in the ink line, the side away from the light stippled, tops a step lighter toward paper. Boxes and arches are
// in ../buildings.ts; these add the round forms.
import { shade, tintOf } from "../buildings"
import {
  circle,
  crescent,
  ellipse,
  line,
  shape,
  stipple,
  tint,
} from "../motifs"
import { n, type Pen } from "../svg"

/** An upright cylinder standing on `base`: its body, the shaded right side, and a lighter elliptical top. */
export function cylinder(
  p: Pen,
  {
    cx,
    base,
    rx,
    h,
    fill,
    ry = rx * 0.32,
    top = true,
  }: {
    cx: number
    base: number
    rx: number
    h: number
    fill: string
    ry?: number
    top?: boolean
  },
) {
  const t = base - h
  const body = `M ${n(cx - rx)} ${n(t)} V ${n(base)} A ${n(rx)} ${n(ry)} 0 0 0 ${n(cx + rx)} ${n(base)} V ${n(t)} Z`
  const x1 = cx + rx * 0.38
  const foot = base + ry * Math.sqrt(1 - 0.38 ** 2)
  const side = `M ${n(x1)} ${n(t)} V ${n(foot)} A ${n(rx)} ${n(ry)} 0 0 0 ${n(cx + rx)} ${n(base)} V ${n(t)} Z`
  return (
    shape(p, body, fill) +
    tint(side, shade(fill)) +
    tint(side, stipple(p)) +
    shape(p, body, "none") +
    (top ? shape(p, ellipse(cx, t, rx, ry), tintOf(fill, 62)) : "")
  )
}

/** A cone (a spire, a roof, a tree) on an elliptical foot, its right half in shade. */
export function cone(
  p: Pen,
  {
    cx,
    base,
    rx,
    h,
    fill,
    ry = rx * 0.3,
  }: {
    cx: number
    base: number
    rx: number
    h: number
    fill: string
    ry?: number
  },
) {
  const apex = `${n(cx)} ${n(base - h)}`
  const body = `M ${apex} L ${n(cx - rx)} ${n(base)} A ${n(rx)} ${n(ry)} 0 0 0 ${n(cx + rx)} ${n(base)} Z`
  const side = `M ${apex} L ${n(cx + rx * 0.2)} ${n(base + ry * 0.98)} A ${n(rx)} ${n(ry)} 0 0 0 ${n(cx + rx)} ${n(base)} Z`
  return (
    shape(p, body, fill) +
    tint(side, shade(fill)) +
    tint(side, stipple(p)) +
    shape(p, body, "none")
  )
}

/** A dome on `base`: a half disc, stippled on its lower right, with a band at its foot. */
export function dome(
  p: Pen,
  { cx, base, r, fill }: { cx: number; base: number; r: number; fill: string },
) {
  const d = `M ${n(cx - r)} ${n(base)} A ${n(r)} ${n(r)} 0 0 1 ${n(cx + r)} ${n(base)} Z`
  const shadow = crescent(cx, base, r, -r * 0.4, -r * 0.3)
  const clip = p.uid("dome")
  return (
    `<clipPath id="${clip}"><path d="${d}"/></clipPath>` +
    shape(p, d, fill) +
    `<g clip-path="url(#${clip})">${tint(shadow, shade(fill))}${tint(shadow, stipple(p))}</g>` +
    shape(p, d, "none")
  )
}

/** A sphere: a disc in a fill, stippled on its lower right. */
export const sphere = (
  p: Pen,
  cx: number,
  cy: number,
  r: number,
  fill: string,
) =>
  tint(circle(cx, cy, r), fill) +
  tint(crescent(cx, cy, r, -r * 0.42, -r * 0.34), shade(fill)) +
  tint(crescent(cx, cy, r, -r * 0.42, -r * 0.34), stipple(p)) +
  shape(p, circle(cx, cy, r), "none")

/** A flat slab seen from above at the oblique: a thin disc of `fill` with its rim showing. */
export function slab(
  p: Pen,
  {
    cx,
    y,
    rx,
    thick,
    fill,
    ry = rx * 0.3,
  }: {
    cx: number
    y: number
    rx: number
    thick: number
    fill: string
    ry?: number
  },
) {
  const rim = `M ${n(cx - rx)} ${n(y)} V ${n(y + thick)} A ${n(rx)} ${n(ry)} 0 0 0 ${n(cx + rx)} ${n(y + thick)} V ${n(y)} Z`
  return (
    shape(p, rim, shade(fill, 70)) +
    tint(rim, stipple(p)) +
    shape(p, rim, "none") +
    shape(p, ellipse(cx, y, rx, ry), tintOf(fill, 70))
  )
}

/** A straight pole or rod from (x0, y0) to (x1, y1), drawn as a thin filled bar of `w`. */
export function rod(
  p: Pen,
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  w: number,
  fill: string,
) {
  const len = Math.hypot(x1 - x0, y1 - y0) || 1
  const [ux, uy] = [((y0 - y1) / len) * (w / 2), ((x1 - x0) / len) * (w / 2)]
  const d = `M ${n(x0 + ux)} ${n(y0 + uy)} L ${n(x1 + ux)} ${n(y1 + uy)} L ${n(x1 - ux)} ${n(y1 - uy)} L ${n(x0 - ux)} ${n(y0 - uy)} Z`
  return shape(p, d, fill)
}

/** A thin ink line, for strings, rigging and hairline details. */
export const wire = (p: Pen, d: string) => line(p, d)

// Objects: the garden, continued. Each object draws in its own box; see library.ts for the contract and architecture.ts
// for the bar. The path tag, curves, bands, leaves and pots come from garden.ts.
import { archPath, box, DEPTH, shade, tintOf } from "../buildings"
import * as M from "../motifs"
import { el, n } from "../svg"
import { cylinder } from "./forms"
import * as G from "./garden"
import { fillOf, type Thing } from "./library"

const { ball, circle, crescent, ellipse, line, shape, sparkle } = M
const { stipple, tint } = M
const { arc, at, cat, cubic, d, garden, leaf, lerp, pol, pot } = G
const { solid, stem, xy } = G
type P = G.P
type P3 = [number, number, number]
const keys = (k: number) => [...Array(k).keys()]

/** Three daisies, paper petals round a sun centre, on stems of different heights with leaves at their foot. */
const art: Thing["draw"] = (p, r, F) => {
  const [lf, pf] = [fillOf(F, "leaves", "leaf"), fillOf(F, "petals", "paper")]
  const s = r("heads")
  const heads: P3[] = [
    [s.between(54, 62), s.between(140, 166), 34],
    [s.between(112, 122), s.between(46, 66), 39],
    [s.between(166, 174), s.between(104, 124), 32],
  ]
  const stems = heads.map(([x, y], i) => {
    const c: P = [x + (110 - x) * 0.25, y + (340 - y) * 0.45]
    return cubic([110, 340], [110 + (i - 1) * 6, 280], c, [x, y], 18)
  })
  const head = ([x, y, R]: P3, i: number) => {
    const [rc, g] = [R * 0.34, s.between(-14, 14)]
    const mid = (rc * 0.8 + R) / 2
    const e = ellipse(mid, 0, (R - rc * 0.8) / 2, mid * 0.215)
    const turn = (a: number) => ({ transform: `rotate(${n(a)})` })
    const as = keys(13).map((j) => (j * 360) / 13 + i * 9)
    const dark = as.filter((a) => (a + g + 355) % 360 <= 90)
    const fill = cat(as, (a) => shape(p, e, pf, turn(a)))
    const marks = cat(dark, (a) => tint(e, stipple(p), turn(a)))
    const k = n(s.between(0.78, 0.95))
    const t = `translate(${n(x)} ${n(y)}) rotate(${n(g)}) scale(1 ${k})`
    const eye = ball(p, 0, 0, rc, fillOf(F, "centre", "sun"))
    return el("g", { transform: t }, fill + marks + eye)
  }
  const ls = r("leaves")
  const leaves = cat([-1, 1, -1, 1], (k, i) => {
    const [L, a] = [ls.between(56, 74), (i < 2 ? 52 : 70) / 57.3]
    const tip: P = [110 + k * Math.cos(a) * L, 338 - Math.sin(a) * L]
    const c: P = [110 + k * Math.cos(a) * L * 0.3, 338 - L * 0.62]
    return leaf(p, [110 + k * 2, 338], tip, 22, lf, c)
  })
  const knees = [at(at(stems, 0), 9), at(at(stems, 2), 10)]
  const mids = cat(knees, (q, i) => {
    return leaf(p, q, [q[0] + (i ? 30 : -30), q[1] - 26], 14, lf)
  })
  const st = fillOf(F, "stem", "leaf")
  const flowers = cat([1, 0, 2], (i) => head(at(heads, i), i))
  return cat(stems, (q) => stem(p, q, 5, 4, st)) + mids + leaves + flowers
}
const daisies = garden("daisy-bunch", "a bunch of daisies", [220, 340], art)

/** A tall allium: a straight stem carrying a ball of tiny star florets, two strap leaves at its foot. */
const allium = garden("allium", "an allium", [170, 420], (p, r, F) => {
  const lf = fillOf(F, "leaves", "leaf")
  const foot: P = [84, 420]
  const R = r("size").between(56, 64)
  const H: P = [r("x").between(84, 92), r("y").between(R + 6, R + 24)]
  const strap = (k: number) => {
    const s = r(`leaf${k}`)
    const tip: P = [84 + k * s.between(60, 74), 420 - s.between(110, 160)]
    return leaf(p, foot, tip, 17, lf, [84 + k * 6, tip[1] - s.between(10, 30)])
  }
  const pt = (i: number) => pol(H, (i / 26) * Math.PI * 2, R)
  const bumps = cat(keys(26), (i) => d` A 7.8 7.8 0 0 1 ${pt(i + 1)}`)
  const florets = cat(keys(40), (i) => {
    const q = pol(H, i * 2.39996, R * 0.86 * Math.sqrt((i + 0.5) / 40))
    return i % 3 === 1 ? sparkle(p, ...q, 4.6) : tint(circle(...q, 1.9), "ink")
  })
  const bloom = fillOf(F, "head", r("colour").pick(["tone-4", "bloom"]))
  const shadow = crescent(...H, R * 1.1, -R * 0.46, -R * 0.36)
  const head = solid(p, d`M ${pt(0)}${bumps} Z`, bloom, shadow)
  const st = cubic(foot, [80, 330], [H[0] + 4, 220], H)
  const stalk = stem(p, st, 7, 5.5, fillOf(F, "stem", "leaf"))
  return stalk + strap(-1) + strap(1) + head + florets
})

/** A fern: arching fronds of paired leaflets from one clump, and sometimes a curled fiddlehead. */
const fern = garden("fern", "a fern", [280, 240], (p, r, F) => {
  const lf = fillOf(F, "fronds", "leaf")
  const B: P = [140, 236]
  const s = r("fronds")
  const plan = [-1, -0.5, 0.1, 0.6, 1].map((l): P => [l, s.between(150, 196)])
  plan.sort((a, b) => Math.abs(a[0]) - Math.abs(b[0]))
  const fronds = cat(plan, ([l, h]) => {
    const [g, sp] = [Math.sign(l) || 1, Math.abs(l)]
    const Hf = h * (1 - sp * 0.25)
    const c1: P = [B[0] + g * sp * 25, B[1] - Hf * 0.85]
    const c2: P = [B[0] + g * (30 + sp * 76), B[1] - Hf * 1.05]
    const end: P = [B[0] + g * (44 + sp * 62), B[1] - Hf * (0.84 - sp * 0.46)]
    const pts = cubic(B, c1, c2, end, 40)
    let out = ""
    for (let i = 4; i < 39; i += 3) {
      const [q, a, b] = [at(pts, i), at(pts, i - 1), at(pts, i + 1)]
      const tg = Math.atan2(b[1] - a[1], b[0] - a[0])
      const len = 26 * (1 - i / 40) ** 0.75 + 5
      for (const k of [-1, 1]) {
        const mid = lerp(q, pol(q, tg + k * 0.85, len), 0.55)
        out += leaf(p, q, pol(q, tg + k * 1.05, len), len * 0.3, lf, mid)
      }
    }
    return out + stem(p, pts, 4.5, 1.6, fillOf(F, "stalk", "leaf"))
  })
  const top: P = [B[0] - 22, B[1] - 66]
  const turn = (i: number) => pol(top, (i / 33) * 10.7 + 3.14, 9 - (9 * i) / 38)
  const coil =
    "M " +
    keys(34)
      .map((i) => xy(turn(i)))
      .join(" L ")
  const c: P = [top[0] - 16, top[1] + 16]
  const stalk = cubic(B, [B[0] - 4, B[1] - 30], c, [top[0] - 9, top[1]], 12)
  const head = shape(p, circle(...top, 10), lf) + line(p, coil)
  const curl = stem(p, stalk, 5, 4, lf) + head
  return fronds + (r("fiddlehead").chance(0.7) ? curl : "")
})

/** The urn's half profile, radius then height, from the lip down to the foot. */
const PROF = [
  38, 96, 40, 104, 26, 112, 23, 124, 34, 136, 53, 160, 48, 190, 30, 210, 13,
  220, 11, 230, 16, 240, 24, 246, 24, 254,
]
/** Points through a profile, smoothed: quadratics through the midpoints, the points as controls. */
const smooth = (pts: P[]) =>
  cat(pts.slice(1, -1), (a, i) => {
    const b = at(pts, i + 2)
    return d` Q ${a} ${i === pts.length - 3 ? b : lerp(a, b, 0.5)}`
  })

/** A classical urn on a short plinth, a plant spilling over its rim. */
const urn = garden("urn", "an urn", [200, 300], (p, r, F) => {
  const f = fillOf(F, "urn", r("urn").pick(["tone-1", "tone-4", "plane-2"]))
  const [lf, bl] = [fillOf(F, "plant", "leaf"), fillOf(F, "bloom", "bloom")]
  const cx = 109
  const side = (k: number) =>
    PROF.flatMap((v, i): P[] => (i % 2 ? [] : [[cx + k * v, at(PROF, i + 1)]]))
  const [right, left, inner] = [side(1), side(-1).reverse(), side(0.38)]
  const body = d`M ${at(right, 0)}${smooth(right)} A 24 5 0 0 1 ${at(left, 0)}${smooth(left)} Z`
  const reg = d`M ${at(inner, 0)}${smooth(inner)} H ${cx + 70} V 90 Z`
  const ring = (rr: number, y: number) =>
    line(p, d`M ${cx - rr} ${y} A ${rr} ${rr * 0.28} 0 0 0 ${cx + rr} ${y}`)
  const flute = (k: number) =>
    line(p, d`M ${cx + k * 10} 210 Q ${cx + k * 19} 192 ${cx + k * 17} 172`)
  const handle = (k: number) => {
    const c = (x: number, y: number): P => [cx + k * x, y]
    const pts = cubic(c(22, 116), c(62, 98), c(66, 140), c(44, 150), 16)
    return stem(p, pts, 7, 5, f)
  }
  const mound = cat([-0.9, -0.45, 0, 0.45, 0.9], (k) => {
    const tip: P = [cx + k * 40, 64 + Math.abs(k) * 16]
    return leaf(p, [cx + k * 10, 98], tip, 16, lf)
  })
  const s = r("trail")
  const vine = (k: number) => {
    const c = (x: number, y: number): P => [cx + k * x, y]
    const drop = k < 0 ? s.between(100, 150) : s.between(40, 70)
    const end = c(s.between(56, 64), 100 + drop)
    const pts = cubic(c(22, 98), c(54, 84), c(64, 118), end)
    const fl = s.chance(0.6)
    const leaves = cat([5, 9, 13, 17, 21], (i) => {
      const [q, o] = [at(pts, i), (i - 5) % 8 ? -1 : 1]
      const bud = i === 13 && fl ? ball(p, q[0] - o * 6, q[1] + 4, 5, bl) : ""
      return leaf(p, q, [q[0] + o * 15, q[1] + 10], 10, lf) + bud
    })
    const last = leaf(p, end, [end[0] + k * 4, end[1] + 16], 9, lf)
    return stem(p, pts, 3, 2.4, lf) + leaves + last
  }
  const pl = fillOf(F, "plinth", "structure")
  const lip = shape(p, ellipse(cx, 96, 38, 10), tintOf(f, 62))
  const mouth = shape(p, ellipse(cx, 97, 30, 7), "ink")
  const bands = ring(23, 124) + ring(30, 210) + ring(16, 240)
  const vase = solid(p, body, f, reg) + bands + cat([-2, -1, 0, 1, 2], flute)
  const plant = lip + mouth + mound + vine(-1) + vine(1)
  const stand = box(p, { x: 52, y: 258, w: 100, h: 42, fill: pl, depth: 0.6 })
  return stand + handle(-1) + handle(1) + vase + plant
})

/** A fountain: a round basin, a column carrying a bowl, a jet, and water falling in paper arcs. */
const fountain = garden("fountain", "a fountain", [300, 300], (p, r, F) => {
  const tone = r("stone").pick(["tone-1", "tone-4", "structure"])
  const stone = fillOf(F, "stone", tone)
  const water = fillOf(F, "water", "highlight")
  const [cx, yb, rb] = [150, r("bowl").between(118, 132), 72]
  const bowl = d`M ${cx - rb} ${yb} A ${rb} 30 0 0 0 ${cx + rb} ${yb} Z`
  const fall = (pts: P[], w: number) => stem(p, pts, w, 1.3, "paper")
  const drop = (x: number, y: number) => shape(p, circle(x, y, 2.3), "paper")
  const cyl = (base: number, rx: number, h: number, ry?: number) =>
    cylinder(p, { cx, base, rx, h, fill: stone, ry, top: false })
  const s = r("water")
  const arcs = (k: number, j: number) => {
    const [x0, y0] = [cx + k * rb * (0.98 - j * 0.24), yb + 1 + j * 9]
    const xe = cx + k * (rb + 28 - j * 20 + s.between(-3, 3))
    const ye = 236 + j * 4
    const c1: P = [x0 + k * (20 - j * 5), y0 - 12 + j * 4]
    const pts = cubic([x0, y0], c1, [xe + k * 4, y0 + 34], [xe, ye])
    const splash = line(p, ellipse(xe, ye + 2, 9 - j, 2.4))
    const spray = j ? "" : drop(xe + k * 9, ye - 10) + drop(xe - k * 7, ye - 14)
    return fall(pts, 6 - j * 0.8) + splash + spray
  }
  const jet = (k: number) => {
    const c = (x: number, y: number): P => [cx + k * x, yb - y]
    return fall(cubic(c(0, 36), c(3, 66), c(30, 66), c(42, 2), 20), 5.5)
  }
  const rim = shape(p, ellipse(cx, 232, 128, 28), tintOf(stone, 62))
  const pool = shape(p, ellipse(cx, 234, 114, 22), water)
  const ripple = line(p, d`M ${cx - 64} 238 A 64 13 0 0 0 ${cx + 64} 238`)
  const shadow = crescent(cx, yb - 12, rb * 1.04, -rb * 0.5, -rb * 0.3)
  const lid = shape(p, ellipse(cx, yb, rb, 16), tintOf(stone, 62))
  const well = shape(p, ellipse(cx, yb + 1, rb - 9, 11.5), water)
  const knob = ball(p, cx, yb - 30, 9, fillOf(F, "finial", "sun"))
  const lower = cyl(268, 128, 36, 28) + rim + pool + ripple
  const upper = cyl(238, 12, 238 - yb) + solid(p, bowl, stone, shadow)
  const top = lid + well + cyl(yb + 2, 6, 26) + knob + jet(-1) + jet(1)
  return lower + upper + top + cat([-1, 1], (k) => arcs(k, 0) + arcs(k, 1))
})

/** A clipped hedge arch: a thick round arch of hedge on two piers, the sky through it, sometimes a ball on top. */
const hedge = garden("hedge-arch", "a hedge arch", [290, 320], (p, r, F) => {
  const f = fillOf(F, "hedge", "leaf")
  const [dx, dy] = [DEPTH[0] * 0.9, DEPTH[1] * 0.9]
  const [cx, foot, R, ri] = [128, 318, 108, r("opening").between(54, 62)]
  const [spring, x1] = [foot - 258 + R, cx + R]
  const T: P = [cx - R * 0.53, spring - R * 0.85]
  const top = d`M ${T} L ${[T[0] + dx, T[1] + dy]} A ${R} ${R} 0 0 1 ${[x1 + dx, spring + dy]} L ${[x1, spring]} A ${R} ${R} 0 0 0 ${T} Z`
  const face = d`M ${[x1, spring]} L ${[x1 + dx, spring + dy]} V ${foot + dy} L ${[x1, foot]} Z`
  const tall = foot - spring
  const opening = archPath(cx - ri, foot, ri * 2, tall + ri)
  const back = archPath(cx - ri + dx, foot + dy, ri * 2, tall + ri)
  const front = `${archPath(cx - R, foot, R * 2, tall + R)} ${opening}`
  const [id, reveal] = [p.uid("arch"), `${opening} ${back}`]
  const eo = { "fill-rule": "evenodd" }
  const inner = shape(p, reveal, shade(f), eo) + tint(reveal, stipple(p), eo)
  const cut = el("clipPath", { id }, el("path", { d: opening }, null))
  const g = el("g", { "clip-path": `url(#${id})` }, inner + line(p, back))
  const s = r("sprigs")
  const sprigs = cat([0, 1, 2, 3], (i) => {
    const a = (205 + i * 42 + s.between(-12, 12)) / 57.3
    const [c, sn, L] = [Math.cos(a), Math.sin(a), s.between(12, 18)]
    const b = pol([cx, spring], a, R - 3)
    const t: P = [b[0] + c * L - sn * 4, b[1] + sn * L + c * 4]
    return leaf(p, b, t, 8, f)
  })
  const knob: P = [cx + dx / 2, spring - R + dy / 2]
  const pole = stem(p, [pol(knob, 1.57, 4), pol(knob, -1.57, 18)], 6, 6, f)
  const orb = ball(p, knob[0], knob[1] - 30, 15, fillOf(F, "ball", "leaf"))
  const sides = shape(p, face, shade(f)) + tint(face, stipple(p))
  const wall = shape(p, front, f, eo) + cut + g + shape(p, opening, "none")
  const ball1 = r("finial").chance(0.7) ? pole + orb : ""
  return sides + shape(p, top, tintOf(f, 70)) + wall + sprigs + ball1
})

/** A small orange tree in a pot: a round crown of leafy puffs with fruit in it. */
const tree = garden("orange-tree", "an orange tree", [180, 300], (p, r, F) => {
  const f = fillOf(F, "crown", "leaf")
  const cx = 90
  const tone = fillOf(F, "pot", r("pot").pick(["tone-1", "tone-4", "plane-2"]))
  const vase = pot(p, [cx, 300], [80, 66], tone)
  const C: P = [cx, r("height").between(88, 102)]
  const s = r("puffs")
  const turn = s.between(0, 0.8)
  const lobes = keys(8).map((i) => {
    const a = turn + (i * Math.PI) / 4
    return { a, c: pol(C, a, 40, 0.95), r: s.between(25, 29) }
  })
  const parts = circle(...C, 46) + cat(lobes, (q) => " " + circle(...q.c, q.r))
  const low = lobes.filter((q) => Math.sin(q.a) > 0.5)
  const contours = cat(low, (q) => arc(p, q.c, q.r, 204, 250))
  const fs = r("fruit")
  const [fruit, want]: [P[], number] = [[], fs.int(7, 11)]
  for (let k = 0; k < 80 && fruit.length < want; k++) {
    const q = pol(C, fs.between(0, 6.28), 56 * Math.sqrt(fs.next()))
    const far = fruit.every((o) => Math.hypot(o[0] - q[0], o[1] - q[1]) > 19)
    if (far) fruit.push(q)
  }
  const id = p.uid("crown")
  const shadow = crescent(...C, 72, -30, -24)
  const marks = tint(shadow, shade(f)) + tint(shadow, stipple(p))
  const edge = line(p, parts, { "stroke-width": p.L * 2 })
  const cut = el("clipPath", { id }, el("path", { d: parts }, null))
  const crown = edge + tint(parts, f) + cut
  const shaded = el("g", { "clip-path": `url(#${id})` }, marks)
  const base: P = [cx, vase.soil + 4]
  const wood = fillOf(F, "trunk", "stair")
  const trunk = stem(p, [base, [cx, C[1] + 30]], 9, 7, wood)
  const sun = fillOf(F, "fruit", "sun")
  const oranges = cat(fruit, (q) => ball(p, ...q, 7.5, sun))
  return vase.svg + trunk + crown + shaded + contours + oranges
})

export const GARDEN_MORE = [daisies, allium, fern, urn, fountain, hedge, tree]

// Objects: the garden. Each object draws in its own box; see library.ts for the contract and architecture.ts for the bar.
// Leaves are the house leaf (plants.ts): pointed, a midrib, stipple on the half away from the light. The helpers here
// (a path tag, curves, bands, leaves, pots) are shared with garden-more.ts.
import { box, shade, tintOf } from "../buildings"
import * as M from "../motifs"
import { el, n, type Pen } from "../svg"
import { sphere } from "./forms"
import { fillOf, type Thing } from "./library"

const { ball, circle, crescent, ellipse, line, shape, stipple, tint } = M
export type P = readonly [number, number]
type V = P | number | string | undefined
export const xy = ([x, y]: P) => `${n(x)} ${n(y)}`
const n2 = (v?: number | string) => (typeof v === "number" ? n(v) : (v ?? ""))
const fmt = (v: V) => (typeof v === "object" ? xy(v) : n2(v))
/** A path from a template: points print as "x y", numbers are rounded. */
export const d = (s: TemplateStringsArray, ...v: V[]) =>
  s.reduce((o, t, i) => o + t + fmt(v[i]), "")
export const lerp = (a: P, b: P, t: number): P => [
  a[0] + (b[0] - a[0]) * t,
  a[1] + (b[1] - a[1]) * t,
]
/** The point at angle a (radians) and radius r from c, squashed by k. */
export const pol = (c: P, a: number, r: number, k = 1): P => [
  c[0] + Math.cos(a) * r,
  c[1] + Math.sin(a) * r * k,
]
/** The item at i (negative counts from the end), clamped to the list. */
export const at = <T>(a: readonly T[], i: number) =>
  a[Math.max(0, Math.min(a.length - 1, i < 0 ? a.length + i : i))] as T
export const cat = <T>(a: readonly T[], f: (x: T, i: number) => string) =>
  a.map(f).join("")
const qAt = (a: P, c: P, b: P, t: number) =>
  lerp(lerp(a, c, t), lerp(c, b, t), t)
const unitN = (a: P, b: P): P => {
  const len = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1
  return [(a[1] - b[1]) / len, (b[0] - a[0]) / len]
}
type Draw = Thing["draw"]
/** A Thing in the garden collection. */
export const garden = (name: string, title: string, w: P, draw: Draw) =>
  ({ name, title, collection: "garden", w: w[0], h: w[1], draw }) as Thing

/** `k + 1` points along a cubic from a to e. */
export const cubic = (a: P, b: P, c: P, e: P, k = 24): P[] =>
  Array.from({ length: k + 1 }, (_, i) =>
    qAt(lerp(a, b, i / k), lerp(b, c, i / k), lerp(c, e, i / k), i / k),
  )

/** A band along points, tapering from w0 to w1: its outline, and the strip on the side away from the light. */
export function band(pts: P[], w0: number, w1: number) {
  const nrm = pts.map((_, i) => unitN(at(pts, i && i - 1), at(pts, i + 1)))
  const s = nrm.reduce((t, [x, y]) => t + x + y, 0) > 0 ? 1 : -1
  const off = (k: number) =>
    pts.map(([x, y], i) => {
      const [nx, ny] = at(nrm, i)
      const w = ((w0 + ((w1 - w0) * i) / (pts.length - 1)) / 2) * k
      return [x + nx * w, y + ny * w] as P
    })
  const path = (a: string[], b: string[]) =>
    `M ${[...a, ...b.reverse()].join(" L ")} Z`
  const pt = (k: number) => off(k).map(xy)
  return { d: path(pt(1), pt(-1)), half: path(pt(s * 0.3), pt(s)) }
}

/** A filled shape whose part inside `reg` is shaded and stippled, outlined again on top. */
export function solid(p: Pen, s: string, f: string, reg: string, clip = true) {
  const id = p.uid("solid")
  const marks = tint(reg, shade(f)) + tint(reg, stipple(p))
  const inner = clip
    ? el("clipPath", { id }, el("path", { d: s }, null)) +
      el("g", { "clip-path": `url(#${id})` }, marks)
    : marks
  return shape(p, s, f) + inner + shape(p, s, "none")
}

/** A stem or trunk along points, its strip away from the light stippled. */
export const stem = (p: Pen, pts: P[], w0: number, w1: number, f: string) => {
  const b = band(pts, w0, w1)
  return shape(p, b.d, f) + tint(b.half, stipple(p)) + shape(p, b.d, "none")
}

/** The house leaf from b to t, its midline bowed through c: fill, stipple on the half away from the light, and a
 * midrib when it is long enough to carry one. `w` is how far the edges' controls stand off the midline. */
export function leaf(p: Pen, b: P, t: P, w: number, f: string, c?: P) {
  const m = c ?? lerp(b, t, 0.5)
  const nr = unitN(b, t)
  const s = nr[0] + nr[1] >= 0 ? 1 : -1
  const e = (k: number): P => [m[0] + nr[0] * w * k, m[1] + nr[1] * w * k]
  const all = d`M ${b} Q ${e(1)} ${t} Q ${e(-1)} ${b} Z`
  const half = d`M ${b} Q ${e(s)} ${t} Q ${m} ${b} Z`
  const rib = d`M ${b} Q ${m} ${t}`
  const mid = Math.hypot(t[0] - b[0], t[1] - b[1]) < 32 ? "" : line(p, rib)
  return shape(p, all, f) + tint(half, stipple(p)) + mid
}

/** A flower pot standing at `foot`, `w` by `h`: a tapered or round body, a rolled rim, soil in ink. */
export function pot(p: Pen, [cx, foot]: P, [w, h]: P, f: string, round = 0) {
  const [rw, ry] = [w / 2, w * 0.14]
  const [bw, bb, e] = [rw * 0.9, rw * (round ? 0.5 : 0.64), rw * 0.18]
  const top = foot - h + ry
  const y0 = top + h * 0.22
  const body = round
    ? d`M ${[cx - bw, y0]} C ${[cx - bw * 1.2, foot - h * 0.3]} ${[cx - bb, foot]} ${[cx, foot]} C ${[cx + bb, foot]} ${[cx + bw * 1.2, foot - h * 0.3]} ${[cx + bw, y0]} Z`
    : d`M ${[cx - bw, y0]} L ${[cx - bb, foot - e]} A ${bb} ${e} 0 0 0 ${[cx + bb, foot - e]} L ${[cx + bw, y0]} Z`
  const reg = round
    ? crescent(cx, foot - bw * 0.95, bw * 1.25, -bw * 0.55, -bw * 0.3)
    : d`M ${[cx + bw * 0.38, y0]} L ${[cx + bb * 0.38, foot + 2]} H ${cx + w} V ${y0} Z`
  const rim = d`M ${[cx - rw, top]} V ${y0} A ${rw} ${ry} 0 0 0 ${[cx + rw, y0]} V ${top} Z`
  const rimShade = d`M ${[cx + rw * 0.38, top]} V ${y0 + ry} H ${cx + rw} V ${top} Z`
  const soil = ellipse(cx, top + ry * 0.12, rw * 0.8, ry * 0.68)
  const lip = shape(p, ellipse(cx, top, rw, ry), tintOf(f, 62))
  const svg = solid(p, body, f, reg) + solid(p, rim, f, rimShade) + lip
  return { soil: top, svg: svg + shape(p, soil, "ink") }
}

/** A short arc of radius `rr` round c from a0 to a1 (degrees, clockwise): an inner contour on a round form. */
export const arc = (p: Pen, c: P, rr: number, a0: number, a1: number) => {
  const [s, t] = [pol(c, a0 / 57.3, rr), pol(c, a1 / 57.3, rr)]
  return line(p, d`M ${s} A ${rr} ${rr} 0 0 1 ${t}`)
}

/** A flame-shaped cypress on a short trunk, stippled down its right side, a few flame lines inside. */
const cypress = garden("cypress", "a cypress", [120, 400], (p, r, F) => {
  const f = fillOf(F, "foliage", "leaf")
  const [cx, yb, W] = [58, 372, r("width").between(50, 60)]
  const lean = r("lean").between(-4, 9)
  const yt = r("height").between(8, 44)
  const H = yb - yt
  const tip: P = [cx + lean, yt]
  const left = d`M ${[cx - W * 0.5, yb]} C ${[cx - W * 1.15, yb - H * 0.35]} ${[cx - W * 0.35, yt + H * 0.3]} ${tip}`
  const right = d`C ${[cx + W * 0.45 + lean * 0.5, yt + H * 0.3]} ${[cx + W * 1.15, yb - H * 0.35]} ${[cx + W * 0.5, yb]}`
  const foot = d`A ${W * 0.5} ${W * 0.22} 0 0 1 ${[cx - W * 0.5, yb]} Z`
  const side = d`M ${tip} C ${[cx + W * 0.1, yt + H * 0.4]} ${[cx + W * 0.45, yb - H * 0.25]} ${[cx + W * 0.2, yb + W * 0.3]} H ${cx + W * 1.5} V ${yt} Z`
  const s = r("lines")
  const flames = cat([-0.5, -0.24, 0.04, 0.3].slice(0, s.int(3, 4)), (k) => {
    const y0 = yb - H * s.between(0.05, 0.22)
    const y1 = yt + H * s.between(0.16, 0.4)
    const c: P = [cx + k * W * 1.3 + lean * 0.3, (y0 + y1) / 2]
    const e: P = [cx + k * W * 0.3 + lean * 0.7, y1]
    return line(p, d`M ${[cx + k * W, y0]} Q ${c} ${e}`)
  })
  const wood = fillOf(F, "trunk", "structure")
  const base: P = [cx, 400]
  const trunk = stem(p, [base, [cx, yb - 8]], 11, 10, wood)
  return trunk + solid(p, `${left} ${right} ${foot}`, f, side) + flames
})

/** A clipped ball of a tree on a straight trunk, in a square planter box. */
const topiary = garden("topiary", "a topiary tree", [190, 300], (p, r, F) => {
  const f = fillOf(F, "foliage", "leaf")
  const tub = fillOf(F, "planter", r("tub").pick(["tone-1", "tone-4", "stair"]))
  const [x, y, w] = [34, 236, 104]
  const c: P = [x + w / 2 + 12, y - 7.5]
  const k = (q: P) => lerp(c, q, 0.8)
  const soil = d`M ${k([x, y])} L ${k([x + 24, y - 15])} L ${k([x + w + 24, y - 15])} L ${k([x + w, y])} Z`
  const R = r("size").between(56, 70)
  const o: P = [c[0], c[1] - r("trunk").between(58, 80) - R]
  const belt = line(p, d`M ${x} ${y + 14} H ${x + w}`)
  const wood = fillOf(F, "trunk", "structure")
  return (
    box(p, { x, y, w, h: 64, fill: tub }) +
    (r("band").chance(0.6) ? belt : "") +
    shape(p, soil, "ink") +
    stem(p, [c, [c[0], o[1] + R * 0.5]], 11, 9, wood) +
    sphere(p, o[0], o[1], R, f) +
    arc(p, o, R * 0.78, 196, 246) +
    arc(p, o, R * 0.56, 214, 244)
  )
})

/** A frond: a long arching leaf cut into leaflets along both edges, a midrib, stipple on its lower half. */
function frond(p: Pen, b: P, t: P, c: P, w: number, f: string) {
  const nr = unitN(b, t)
  const side = (k: number) => {
    const e: P = [c[0] + nr[0] * w * k, c[1] + nr[1] * w * k]
    const notch = (u: number) => lerp(qAt(b, c, t, u), qAt(b, e, t, u), 0.14)
    const us = [0.06, 0.16, 0.26, 0.36, 0.46, 0.56, 0.66]
    return us.flatMap((u) => [notch(u), qAt(b, e, t, u + 0.13)])
  }
  const L = (pts: P[]) => pts.map(xy).join(" L ")
  const s = nr[0] + nr[1] >= 0 ? 1 : -1
  const half = d`M ${b} L ${L([...side(s), t])} Q ${c} ${b} Z`
  const all = d`M ${b} L ${L([...side(1), t, ...side(-1).reverse()])} Z`
  const rib = line(p, d`M ${b} Q ${c} ${t}`)
  return shape(p, all, f) + tint(half, stipple(p)) + rib
}

/** A palm: a ringed trunk curving up to a crown of six to eight arching fronds. */
const palm = garden("palm", "a palm tree", [300, 420], (p, r, F) => {
  const lf = fillOf(F, "fronds", "leaf")
  const top: P = [r("x").between(148, 162), r("y").between(138, 156)]
  const pts = cubic([122, 417], [102, 310], [top[0] - 46, 222], top, 14)
  const trunk = band(pts, 30, 17)
  const rings = cat(pts.slice(1, -2), (q, i) => {
    const w = (30 - (13 * (i + 1)) / 14) / 2
    const ring = d`M ${[q[0] - w, q[1] - 2]} Q ${[q[0], q[1] + 5]} ${[q[0] + w, q[1] - 2]}`
    return line(p, ring)
  })
  const s = r("fronds")
  const count = s.int(6, 8)
  const fronds = Array.from({ length: count }, (_, i) => {
    const a = (160 + (220 * i) / (count - 1) + s.between(-8, 8)) / 57.3
    const [L, c] = [s.between(112, 136), Math.cos(a)]
    const tip = pol(top, a, L)
    const bow = pol(top, a, L * 0.55)
    const end: P = [tip[0], tip[1] + L * 0.62 * c * c]
    const lift: P = [bow[0], bow[1] - L * 0.25 * Math.abs(c)]
    return { y: tip[1], svg: frond(p, top, end, lift, L * 0.3, lf) }
  }).sort((x, y) => x.y - y.y)
  const nut = fillOf(F, "nuts", "tone-2")
  const nuts = cat([2.2, 1.2, 0.4], (a) =>
    ball(p, ...pol(top, a, 15), 8.5, nut),
  )
  const wood = fillOf(F, "trunk", "stair")
  const body = solid(p, trunk.d, wood, trunk.half, false) + rings
  return body + cat(fronds, (x) => x.svg) + (r("nuts").chance(0.65) ? nuts : "")
})

/** A columnar cactus with two arms and fine ribs, in a round pot, sometimes in flower. */
const cactus = garden("cactus", "a cactus", [170, 330], (p, r, F) => {
  const f = fillOf(F, "cactus", "leaf")
  const cx = 80
  const tone = fillOf(F, "pot", r("pot").pick(["tone-1", "tone-2", "tone-4"]))
  const vase = pot(p, [cx, 330], [112, 74], tone, 1)
  const [bw, top] = [r("girth").between(23, 27), r("height").between(26, 58)]
  const soil = vase.soil + 4
  const s = r("arms")
  const arm = (k: number) => {
    const [t, ya] = [bw * 1.1, top + (soil - top) * s.between(0.42, 0.62)]
    const [xe, ax] = [cx + k * bw, cx + k * (bw + s.between(24, 32))]
    const ta = ya - s.between(46, 78)
    const [h, sw, fl, i] = [t / 2, k < 0 ? 1 : 0, t * 0.3, ax - (k * t) / 2]
    const out = d`M ${[xe - k * 6, ya + h]} H ${ax} A ${h} ${h} 0 0 ${sw} ${[ax + k * h, ya]} V ${ta}`
    const back = d`A ${h} ${h} 0 0 ${sw} ${[i, ta]} V ${ya - h - fl} Q ${[i, ya - h]} ${[i - k * fl, ya - h]} H ${xe - k * 6} Z`
    const [x0, x1] = [Math.min(ax, xe) - t, Math.max(ax, xe) + t]
    const reg = d`M ${[ax + t * 0.12, ta - t]} H ${ax + t} V ${ya} H ${ax + t * 0.12} Z M ${[x0, ya + t * 0.15]} H ${x1} V ${ya + t} H ${x0} Z`
    const rib = d`M ${[xe, ya]} H ${ax - k * t * 0.3} Q ${[ax, ya]} ${[ax, ya - t * 0.3]} V ${ta - t * 0.1}`
    return solid(p, `${out} ${back}`, f, reg) + line(p, rib)
  }
  const body = d`M ${[cx - bw, soil]} V ${top + bw} A ${bw} ${bw} 0 0 1 ${[cx + bw, top + bw]} V ${soil} Z`
  const ribs = cat([-0.62, -0.24, 0.18, 0.58], (k) => {
    const x = cx + k * bw
    const rib = d`M ${x} ${soil - 2} V ${top + bw} Q ${[x, top + bw * 0.3]} ${[cx + k * bw * 0.15, top + 3]}`
    return line(p, rib)
  })
  const bloom = fillOf(F, "bloom", "bloom")
  const c: P = [cx - 6, top + 2]
  const disc = (i: number) => circle(...pol(c, i * 1.257 - 1.57, 7, 0.86), 6)
  const petals = cat([0, 1, 2, 3, 4], (i) => shape(p, disc(i), bloom))
  const flower = petals + shape(p, circle(c[0], c[1], 3.6), "sun")
  const reg = d`M ${cx + bw * 0.3} 0 H ${cx + bw * 2} V ${soil} H ${cx + bw * 0.3} Z`
  const plant = arm(-1) + arm(1) + solid(p, body, f, reg) + ribs
  return vase.svg + plant + (r("flower").chance(0.65) ? flower : "")
})

/** A tall poppy: a four-petalled bloom with an ink centre, a nodding bud, curving stems and two leaves. */
const poppy = garden("poppy", "a poppy", [200, 400], (p, r, F) => {
  const [lf, st] = [fillOf(F, "leaves", "leaf"), fillOf(F, "stem", "leaf")]
  const petal = fillOf(F, "bloom", r("colour").pick(["bloom", "sun"]))
  const C: P = [r("x").between(104, 118), r("y").between(92, 104)]
  const [R, k] = [r("size").between(42, 47), r("bud").chance(0.5) ? 1 : -1]
  const o = R * 0.68
  const main = cubic([96, 400], [92, 300], [C[0] - 18, 210], C)
  const E: P = [98 + k * 60, r("bud-y").between(170, 196)]
  const bud = cubic([98, 400], [98 + k * 4, 300], [98 + k * 56, E[1] + 62], E)
  const tip: P = [E[0] + k * 32, E[1] - 27]
  const [m9, m6] = [at(main, 9), at(main, 6)]
  const up: P = [m9[0] - 62, m9[1] - 50]
  const out: P = [m6[0] + 58, m6[1] - 34]
  const leaves =
    leaf(p, m9, up, 30, lf, [m9[0] - 22, m9[1] - 44]) +
    leaf(p, m6, out, 26, lf, [m6[0] + 30, m6[1] - 40])
  const shadow = crescent(C[0], C[1], o + R, -(o + R) * 0.42, -(o + R) * 0.34)
  const petals = cat([225, 315, 135, 45], (deg) => {
    const a = deg / 57.3
    const pc = pol(C, a, o, 0.8)
    const crinkle = cat([-0.3, 0.25], (u) => {
      const seam = d`M ${pol(C, a + u, R * 0.55, 0.9)} L ${pol(C, a + u, o + R * 0.6, 0.8)}`
      return line(p, seam)
    })
    return solid(p, circle(pc[0], pc[1], R), petal, shadow) + crinkle
  })
  const dot = (i: number) => circle(...pol(C, i * 0.571, R * 0.3, 0.9), 1.5)
  const dots = cat([...Array(11).keys()], (i) => tint(dot(i), "paper"))
  const eye = shape(p, ellipse(C[0], C[1], R * 0.44, R * 0.4), "ink")
  return (
    stem(p, bud, 6, 5, st) +
    leaf(p, E, tip, 36, fillOf(F, "bud", "leaf")) +
    leaf(p, lerp(E, tip, 0.4), tip, 10, petal) +
    leaves +
    stem(p, main, 7, 5.5, st) +
    petals +
    eye +
    dots +
    ball(p, C[0], C[1], R * 0.15, "leaf")
  )
})

export const GARDEN: Thing[] = [cypress, topiary, palm, cactus, poppy]

// The object library, by collection. A new object goes in its collection's file and its array; it then appears on
// the library page, in <Drawing> and in scenes by name.
import { ARCHITECTURE } from "./architecture"
import { ARCHITECTURE_MORE } from "./architecture-more"
import { GARDEN } from "./garden"
import { GARDEN_MORE } from "./garden-more"
import { INSTRUMENTS } from "./instruments"
import { INSTRUMENTS_MORE } from "./instruments-more"
import { SKY } from "./sky"
import { SKY_MORE } from "./sky-more"
import { STAGE } from "./stage"
import { STAGE_MORE } from "./stage-more"
import { TRAVEL } from "./travel"
import { TRAVEL_MORE } from "./travel-more"
import type { Collection, Thing } from "./library"

export {
  put,
  type Collection,
  type Fills,
  type Placement,
  type Thing,
} from "./library"

const ALL: Thing[] = [
  ...ARCHITECTURE,
  ...ARCHITECTURE_MORE,
  ...SKY,
  ...SKY_MORE,
  ...INSTRUMENTS,
  ...INSTRUMENTS_MORE,
  ...GARDEN,
  ...GARDEN_MORE,
  ...TRAVEL,
  ...TRAVEL_MORE,
  ...STAGE,
  ...STAGE_MORE,
]

export const OBJECTS: Readonly<Record<string, Thing>> = Object.fromEntries(
  ALL.map((t) => [t.name, t]),
)
export type ObjectName = string

/** The collections in the library's order, each with its objects. */
export const COLLECTIONS: {
  name: Collection
  title: string
  things: Thing[]
}[] = (
  [
    ["architecture", "Architecture"],
    ["sky", "The sky"],
    ["instruments", "Instruments"],
    ["garden", "The garden"],
    ["travel", "Travel and post"],
    ["stage", "The stage"],
    ["everyday", "Everyday moments"],
  ] as const
)
  .map(([name, title]) => ({
    name,
    title,
    things: ALL.filter((t) => t.collection === name),
  }))
  .filter((c) => c.things.length > 0)

/** One object from `pool` that the library has, chosen by `r`; undefined if it has none of them. */
export function oneOf(
  r: { pick: <T>(items: readonly T[]) => T },
  pool: readonly string[],
) {
  const have = pool.filter((name) => OBJECTS[name])
  return have.length ? OBJECTS[r.pick(have)] : undefined
}

/** An object by name; throws on a name the library does not have, so a typo fails the build. */
export function thing(name: string): Thing {
  const t = OBJECTS[name]
  if (!t) throw new Error(`No object named "${name}" in the library`)
  return t
}

// Objects: instruments, continued: the compass, the hourglass, the navigator's sextant, a sundial, binoculars, a
// lantern, a weathervane and a key. Tubes, arcs and silhouettes come from instruments.ts.
import { box, DEPTH, quad, shade, tintOf } from "../buildings"
import { circle, crescent, ellipse, line, pinwheel, shape } from "../motifs"
import { sparkle, stipple, tint } from "../motifs"
import { n, type Pen } from "../svg"
import { cone, cylinder, dome, slab, sphere } from "./forms"
import { arc, clip, dark, go, pole, pt, tube, union } from "./instruments"
import { thing, type Draw, type Pt } from "./instruments"
import { fillOf, type Thing } from "./library"

const PI = Math.PI
const ring = (c: Pt, a: number, b: number) =>
  `${circle(c[0], c[1], a)} ${circle(c[0], c[1], b)}`
const odd = { "fill-rule": "evenodd" }
/** A rectangle as a path. */
const rect = (x: number, y: number, w: number, h: number) =>
  `M ${n(x)} ${n(y)} h ${n(w)} v ${n(h)} h ${n(-w)} Z`

const compass: Draw = (p, r, f) => {
  const brass = fillOf(f, "case", "sun")
  const face = fillOf(f, "face", r("face").pick(["tone-4", "highlight"]))
  const [cx, cy, rx, ry] = [128, 100, 112, 47]
  const P = (a: number, d: number) =>
    pt([cx + Math.cos(a) * d, cy + (Math.sin(a) * d * ry) / rx])
  const S = (d: string, fill: string) => shape(p, d, fill)
  const spin = r("rose").between(-0.25, 0.25)
  let rose = ""
  for (let i = 0; i < 8; i++) {
    const a = spin + (i * PI) / 4 - PI / 2
    const [tip, s] = [P(a, i % 2 ? 50 : 82), i % 2 ? 9 : 14]
    const pair =
      S(`M ${cx} ${cy} L ${P(a - PI / 4, s)} L ${tip} Z`, "paper") +
      S(`M ${cx} ${cy} L ${tip} L ${P(a + PI / 4, s)} Z`, "ink")
    rose = i % 2 ? pair + rose : rose + pair
  }
  const tick = (_: unknown, i: number) =>
    `M ${P((i * PI) / 16, 94)} L ${P((i * PI) / 16, i % 4 ? 88 : 82)}`
  const nd = r("needle").between(-1.2, 1.2) - PI / 2
  const [nN, nS] = [P(nd, 74), P(nd + PI, 74)]
  const [nL, nR] = [P(nd - PI / 2, 9), P(nd + PI / 2, 9)]
  const dial = ellipse(cx, cy, rx * 0.86, ry * 0.86)
  const rim = crescent(cx, cy + 10, rx * 0.86, rx * 0.2, ry * 0.5)
  const bow: Pt = [cx, cy - ry - 22]
  const loop = cylinder(p, { cx, base: bow[1] + 18, rx: 8, h: 12, fill: brass })
  const drum = cylinder(p, { cx, base: cy + 30, rx, ry, h: 30, fill: brass })
  const top = S(ellipse(cx, cy, rx, ry), tintOf(brass, 62)) + S(dial, face)
  const ticks = line(p, Array.from({ length: 32 }, tick).join(" "))
  const needle = S(`M ${nN} L ${nL} L ${nS} L ${nR} Z`, "paper")
  const north = S(`M ${nN} L ${nL} L ${nR} Z`, fillOf(f, "needle", "structure"))
  const hub = S(ellipse(cx, cy, 6, 4.5), brass)
  const bezel = clip(p, dial, tint(rim, shade(face, 90)))
  const back = loop + shape(p, ring(bow, 16, 9), brass, odd) + drum
  return back + top + bezel + ticks + rose + needle + north + hub
}

const hourglass: Draw = (p, r, f) => {
  const wood = fillOf(f, "frame", "structure")
  const sand = fillOf(f, "sand", "stair")
  const [c, t, b, m] = [100, 60, 262, 161]
  const side = (s: number, y: number[]) =>
    `C ${c + 66 * s} ${y[0]} ${c + 62 * s} ${y[1]} ${c + 5 * s} ${m} ` +
    `C ${c + 62 * s} ${y[2]} ${c + 66 * s} ${y[3]} ${c + 22 * s} ${y[4]}`
  const down = side(-1, [t + 20, m - 40, m + 40, b - 20, b])
  const up = side(1, [b - 20, m + 40, m - 40, t + 20, t])
  const glass = `M ${c - 22} ${t} ${down} L ${c + 22} ${b} ${up} Z`
  const top = r("sand").between(104, 124)
  const peak = r("sand").between(196, 212)
  const upper = `M 30 ${n(top)} Q ${c} ${n(top + 22)} 170 ${n(top)} V ${m} H 30 Z`
  const lower = `M 30 ${b} V ${n(peak + 34)} Q ${c} ${n(peak - 34)} 170 ${n(peak + 34)} V ${b} Z`
  const post = (a: number) => {
    const [x, dy] = [c + Math.cos(a) * 54, Math.sin(a) * 16]
    const bead = (y: number) => shape(p, ellipse(x, y + dy, 8, 4), wood)
    const bar = pole(p, [x, 276 + dy], [x, 42 + dy], 5, wood)
    return bar + sphere(p, x, m + dy, 8, wood) + bead(78) + bead(244)
  }
  const glint = (y: number) =>
    line(p, `M ${c - 40} ${y + 10} Q ${c - 40} ${y - 14} ${c - 22} ${y - 26}`)
  const lit = (y: number) => tint(crescent(c, y, 54, -26, -16), stipple(p))
  const fill =
    shape(p, upper, sand) + shape(p, lower, sand) + lit(108) + lit(214)
  const stream = shape(p, rect(c - 1.5, m, 3, peak - m), sand)
  const plate = (y: number) =>
    slab(p, { cx: c, y, rx: 76, thick: 18, fill: wood })
  const bulbs = shape(p, glass, "paper") + clip(p, glass, fill) + stream
  const front = shape(p, glass, "none") + glint(110) + glint(216)
  const posts = post((PI * 5) / 6) + post(PI / 6)
  return plate(266) + post(-PI / 2) + bulbs + front + posts + plate(26)
}

/** A bar of width `w` from `a` to `b`, as a path. */
function bar(a: Pt, b: Pt, w: number) {
  const k = w / 2 / Math.hypot(b[0] - a[0], b[1] - a[1])
  const v: Pt = [(b[1] - a[1]) * k, (a[0] - b[0]) * k]
  return quad([go(a, v, 1), go(b, v, 1), go(b, v, -1), go(a, v, -1)])
}

const sextant: Draw = (p, r, f) => {
  const frame = fillOf(f, "frame", "structure")
  const arm = fillOf(f, "arm", "stair")
  const glass = fillOf(f, "mirror", "highlight")
  const A: Pt = [136, 52]
  const P = (d: number, k: number) =>
    go(A, [Math.sin(d / 57.3), Math.cos(d / 57.3)], k)
  const sector = (r0: number, r1: number, d: number) =>
    `M ${pt(P(-d, r1))}${arc(P(-d, r1), P(d, r1), r1, r1, 0, [0, 1])}` +
    ` L ${pt(P(d, r0))}${arc(P(d, r0), P(-d, r0), r0, r0, 0, [0, 1])} Z`
  const tick = (_: unknown, i: number) =>
    `M ${pt(P(i * 2 - 30, 200))} L ${pt(P(i * 2 - 30, i % 5 ? 194 : 190))}`
  const at = r("index").between(-20, 16)
  const limb = sector(174, 204, 32)
  const sides = [bar(A, P(-30, 184), 18), bar(A, P(30, 184), 18)]
  const parts = [limb, ...sides, rect(88, 140, 96, 14), circle(136, 52, 20)]
  const S = (d: string, fill: string) => shape(p, d, fill)
  const handle =
    "M 252 96 Q 276 96 276 124 V 186 Q 276 212 256 212 Q 240 212 240 186 V 124 Q 240 96 252 96 Z"
  const studs = S(`${rect(196, 112, 56, 8)} ${rect(230, 186, 22, 8)}`, frame)
  const grip = S(handle, fillOf(f, "handle", "tone-1")) + studs
  const ticks = line(p, Array.from({ length: 31 }, tick).join(" "))
  const scale = S(sector(189, 201, 30), "paper") + ticks
  const shadow = clip(p, limb, tint(sector(188, 208, 40), stipple(p)))
  const lens = fillOf(f, "scope", "tone-4")
  const scope = tube(p, [232, 126], [146, 126], [10, 12], lens)
  const index = `${bar(A, P(at, 174), 12)} ${bar(P(at, 170), P(at, 208), 16)}`
  const knob =
    S(circle(...P(at + 7, 160), 7), arm) +
    S(circle(136, 52, 6), tintOf(arm, 62))
  const mirrors =
    S(rect(116, 20, 40, 30), glass) + S(rect(116, 106, 14, 40), glass)
  const clear = S(rect(102, 106, 14, 40), "paper")
  const frameD = union(p, parts, frame) + shadow + scale
  return grip + frameD + scope + S(index, arm) + mirrors + clear + knob
}

const sundial: Draw = (p, r, f) => {
  const dial = fillOf(f, "dial", "platform")
  const gnomon = fillOf(f, "gnomon", "sun")
  const stone = fillOf(f, "plinth", "structure")
  const column = fillOf(f, "column", r("column").pick(["tone-1", "tone-4"]))
  const P = (a: number, k: number) =>
    pt([130 + Math.cos(a) * 108 * k, 104 + Math.sin(a) * 36 * k])
  const tick = (_: unknown, i: number) =>
    `M ${P((i * PI) / 12, 0.86)} L ${P((i * PI) / 12, i % 3 ? 0.78 : 0.68)}`
  const top = 98 - r("gnomon").between(62, 76)
  const blade = `M 72 108 L 174 98 L 174 ${n(top)} Z`
  const back = `M 174 98 V ${n(top)} l 5 -3 V 95 Z`
  const edge = `M 72 108 L 174 ${n(top)} l 5 -3 L 77 105 Z`
  const shadow = "M 72 108 L 174 98 L 250 128 Z"
  const ticks = line(p, Array.from({ length: 24 }, tick).join(" "))
  const ring = shape(p, ellipse(130, 104, 93, 31), "none") + ticks
  const cast = clip(p, ellipse(130, 104, 108, 36), dark(p, shadow, dial))
  const S = (d: string, fill: string) => shape(p, d, fill)
  const plate =
    S(back, shade(gnomon)) + S(edge, tintOf(gnomon, 62)) + S(blade, gnomon)
  return (
    cylinder(p, { cx: 130, base: 280, rx: 30, h: 160, fill: column }) +
    slab(p, { cx: 128, y: 270, rx: 64, thick: 16, fill: stone }) +
    slab(p, { cx: 130, y: 126, rx: 44, thick: 12, fill: stone }) +
    slab(p, { cx: 130, y: 104, rx: 108, ry: 36, thick: 16, fill: dial }) +
    ring +
    cast +
    plate
  )
}

/** A barrel seen down its length: a round face at `c`, its body running back along the depth. */
function barrel(p: Pen, c: Pt, r: number, len: number, fill: string) {
  const u: Pt = [DEPTH[0] / 28.3, DEPTH[1] / 28.3]
  const b = go(c, u, len)
  const s = (q: Pt, m: number) => go(q, [-u[1] * r, u[0] * r], m)
  const ends =
    arc(s(b, 1), s(b, -1), r, r, 0, u) +
    ` L ${pt(s(c, -1))}${arc(s(c, -1), s(c, 1), r, r, 0, [-u[0], -u[1]])}`
  const body = `M ${pt(s(c, 1))} L ${pt(s(b, 1))}${ends} Z`
  const strip = quad([s(c, 0.2), s(b, 0.2), s(b, 2), s(c, 2)])
  const shadow = clip(p, body, dark(p, strip, fill))
  return shape(p, body, fill) + shadow + shape(p, body, "none")
}

const binoculars: Draw = (p, r, f) => {
  const body = fillOf(f, "body", r("body").pick(["tone-1", "tone-4", "tone-3"]))
  const rim = fillOf(f, "rim", "structure")
  const metal = fillOf(f, "bridge", "stair")
  const side = (x: number) => {
    const glint = { transform: `rotate(-35 ${x - 14} 144)` }
    const lens =
      shape(p, circle(x, 158, 48), rim) + shape(p, circle(x, 158, 37), "ink")
    const shine = tint(crescent(x, 158, 37, 8, 7), tintOf("ink", 70))
    const tubes =
      barrel(p, [x + 52, 126], 26, 40, "ink") +
      barrel(p, [x, 158], 48, 66, body)
    const gleam = shape(p, ellipse(x - 14, 144, 9, 6), "paper", glint)
    return tubes + lens + shine + gleam
  }
  const hinge =
    barrel(p, [116, 132], 30, 60, metal) +
    shape(p, rect(96, 113, 60, 14), metal) +
    barrel(p, [124, 106], 18, 22, rim) +
    shape(p, circle(124, 106, 18), tintOf(rim, 62))
  const pin =
    shape(p, circle(116, 132, 30), metal) + shape(p, circle(116, 132, 8), "ink")
  return side(62) + hinge + pin + side(176)
}

const lantern: Draw = (p, r, f) => {
  const pick = r("frame").pick(["tone-4", "platform", "plane"])
  const [fr, glow] = [fillOf(f, "frame", pick), fillOf(f, "glass", "sun")]
  const S = (d: string, fill: string) => shape(p, d, fill)
  const block = (x: number, y: number, w: number, h: number) =>
    box(p, { x, y, w, h, fill: fr })
  const roof = "M 130 118 L 154 103 L 92 48 Z"
  const flame = "M 80 194 Q 93 216 80 226 Q 67 216 80 194 Z"
  const side = "M 123 136 l 14 -9 v 142 l -14 9 Z"
  const panes = S(side, shade(glow, 90)) + S(rect(51, 140, 58, 134), glow)
  const candle = S(rect(69, 230, 22, 44), "paper") + S(flame, "paper")
  const feet = S(`${rect(38, 298, 6, 14)} ${rect(116, 298, 6, 14)}`, fr)
  const cap =
    dark(p, roof, fr) + S(roof, "none") + S("M 30 118 H 130 L 92 48 Z", fr)
  const bail =
    sphere(p, 92, 44, 8, fr) + shape(p, ring([92, 18], 18, 11), fr, odd)
  const body =
    block(42, 132, 76, 150) + panes + candle + line(p, "M 51 186 H 109")
  return (
    body + block(32, 282, 96, 16) + feet + block(30, 118, 100, 14) + cap + bail
  )
}

const weathervane: Draw = (p, r, f) => {
  const iron = fillOf(f, "pole", "structure")
  const vane = fillOf(f, "vane", "stair")
  const tail = r("tail").chance(0.5)
    ? "M 8 52 H 74 L 92 86 L 74 120 H 8 L 28 86 Z"
    : "M 10 44 Q 62 50 92 86 Q 62 122 10 128 Q 34 86 10 44 Z"
  const head = "M 246 86 L 194 56 L 202 86 L 194 116 Z"
  const plaque = (x: number, y: number) => rect(x - 8, y - 18, 16, 36)
  const arm = (a: Pt, b: Pt) => pole(p, a, b, 6, iron)
  const mount = fillOf(f, "mount", "tone-4")
  const arms = arm([124, 228], [182, 192]) + arm([44, 228], [204, 228])
  const back = shape(p, plaque(182, 192), vane) + arms
  const plaques = `${plaque(44, 228)} ${plaque(204, 228)} ${plaque(66, 264)}`
  const hub = sphere(p, 124, 228, 9, iron) + arm([124, 228], [66, 264])
  const front = hub + shape(p, plaques, vane)
  const feathers = "M 36 64 L 52 86 L 36 108 M 56 64 L 72 86 L 56 108"
  const under = tint("M 92 86 H 246 L 194 116 L 196 92 H 92 Z", stipple(p))
  const arrow =
    union(p, [tail, rect(40, 80, 164, 12), head], vane) +
    line(p, feathers) +
    under
  const finial =
    cone(p, { cx: 124, base: 60, rx: 9, h: 34, fill: iron }) +
    sphere(p, 124, 86, 11, iron)
  const ball = sphere(p, 124, 162, 24, fillOf(f, "ball", "highlight"))
  const stand =
    dome(p, { cx: 124, base: 356, r: 40, fill: mount }) +
    pole(p, [124, 330], [124, 60], 8, iron)
  return stand + back + front + ball + arrow + finial
}

/** A four-point concave star, as a path. */
function star(x: number, y: number, s: number) {
  const q = (a: number, b: number, c: number, d: number) =>
    ` Q ${n(x + a * s * 0.16)} ${n(y + b * s * 0.16)} ${n(x + c * s)} ${n(y + d * s)}`
  return `M ${x} ${y - s}${q(1, -1, 1, 0)}${q(1, 1, 0, 1)}${q(-1, 1, -1, 0)}${q(-1, -1, 0, -1)} Z`
}

const key: Draw = (p, r, f) => {
  const brass = fillOf(f, "key", "sun")
  const [bx, by, R] = [78, 75, 54]
  const lobe = (t: number) =>
    circle(bx + Math.cos(PI * t) * R, by + Math.sin(PI * t) * R, 14)
  const lobes = r("lobes").chance(0.6) ? [0.75, 1, 1.25].map(lobe) : []
  const bit = `M 238 ${by} H 290 V 134 H 278 V 118 H 266 V 134 H 252 V 120 H 238 Z`
  const parts = [circle(bx, by, R), rect(120, 64, 180, 22), circle(298, by, 13)]
  parts.push(bit, ...lobes)
  const low = crescent(bx, by, R + 14, -R * 0.42, -R * 0.34)
  const under = `${rect(110, by + 4, 210, 7)} ${rect(282, by + 11, 8, 54)}`
  const band = (x: number) =>
    line(p, `M ${x} ${by - 11} v 22 M ${x + 7} ${by - 11} v 22`)
  const [hue, turn] = [fillOf(f, "pinwheel", "highlight"), r("turn").next()]
  const wheel = pinwheel(p, bx, by, 36, hue, { turn })
  const cut = r("cut").chance(0.5)
    ? shape(p, circle(bx, by, 36), "ink") + wheel
    : shape(p, star(bx, by, 34), "ink") + sparkle(p, bx + 48, by - 52, 9)
  const dk = dark(p, low, brass) + dark(p, under, brass)
  const shadow = clip(p, parts.join(" "), dk)
  const ward = shape(p, rect(258, by + 16, 8, 18), "ink")
  return union(p, parts, brass) + shadow + band(130) + band(210) + ward + cut
}

