// The object library: every drawable thing as one draw function filed in a collection, so the library page, scenes
// and <Drawing> find objects the same way. An object draws in its own box, (0, 0) to (w, h), standing on the box's
// foot (y = h) unless it floats; oblique depth runs up and to the right inside the box. Every fill is a colourway
// role, so an object reprints in every colourway; `fills` lets a scene recolour one without redrawing it.
import { el, n, rs, type Pen, type Rs } from "../svg"

export type Collection =
  | "architecture"
  | "sky"
  | "instruments"
  | "garden"
  | "travel"
  | "stage"
  | "everyday"

export interface Thing {
  /** kebab-case, unique across the library. */
  name: string
  /** Its name in a sentence ("a spiral stair"), for labels and the library page. */
  title: string
  collection: Collection
  w: number
  h: number
  /** Draws the object in its box. `r` forks a seeded stream per decision; `fills` overrides its default roles. */
  draw: (p: Pen, r: (label: string) => Rs, fills: Fills) => string
}

/** Role overrides by the object's own part names: { body: "tone-2", roof: "structure" }. */
export type Fills = Record<string, string | undefined>

/** The role for a part: the scene's override, else the object's default. */
export const fillOf = (fills: Fills, part: string, fallback: string) =>
  fills[part] ?? fallback

/** A stream factory for one object drawn from `seed`: each label forks its own stream. */
export const streams = (seed: number, name: string) => (label: string) =>
  rs(seed, `${name}:${label}`)

export interface Placement {
  /** Left edge of the object's box, in the scene's units. */
  x: number
  /** Where its foot stands (the box's bottom edge), in the scene's units. */
  y: number
  /** Its height in the scene's units; the width follows. Defaults to the object's own height. */
  h?: number
  /** Mirror it left to right. */
  flip?: boolean
  /** Its own seed label, so two of the same object in one scene differ. */
  key?: string
  fills?: Fills
}

/** An object placed in a scene: translated and scaled so its foot stands at (x, y) and it is `h` tall. */
export function put(
  p: Pen,
  seed: number,
  thing: Thing,
  { x, y, h = thing.h, flip = false, key = "", fills = {} }: Placement,
) {
  const k = h / thing.h
  const w = thing.w * k
  const move = flip
    ? `translate(${n(x + w)} ${n(y - h)}) scale(${n(-k)} ${n(k)})`
    : `translate(${n(x)} ${n(y - h)}) scale(${n(k)})`
  return el(
    "g",
    { transform: move, "data-object": thing.name },
    thing.draw(p, streams(seed, `${thing.name}:${key}`), fills),
  )
}

// Objects: the sky, continued: a constellation, a rainbow, clouds, a star cluster and the moon's phases. Clouds are
// drawn in painter's order: one ink outline round the whole, then each puff from back to front, shaded on its lower
// right, with open arcs only where a puff in front overlaps one behind.
import { shade, tintOf } from "../buildings"
import { circle, crescent, line, pinpoint, ring, shape } from "../motifs"
import { sparkle, stipple, tint } from "../motifs"
import { n, type Pen, type Rs } from "../svg"
import { fillOf, type Thing } from "./library"
import { dots, looseLine, puff, sky, star } from "./sky"
import type { Block, Draw, Lump } from "./sky"

const DEG = Math.PI / 180

const inside = (q: Lump | Block, x: number, y: number) =>
  "r" in q
    ? (x - q.cx) ** 2 + (y - q.cy) ** 2 < (q.r - 0.4) ** 2
    : x > q.x0 && x < q.x1 && y > q.y0 && y < q.y1
const pathOf = (q: Lump | Block) =>
  "r" in q
    ? circle(q.cx, q.cy, q.r)
    : `M ${n(q.x0)} ${n(q.y0)} H ${n(q.x1)} V ${n(q.y1)} H ${n(q.x0)} Z`

/** Lumps, listed from back to front, drawn as one cloud. */
export function lumps(p: Pen, list: (Lump | Block)[]) {
  const d = list.map(pathOf).join(" ")
  let [body, arcs] = ["", ""]
  list.forEach((q, i) => {
    body += tint(pathOf(q), q.fill)
    if (!("r" in q)) return
    body += tint(crescent(q.cx, q.cy, q.r, -q.r * 0.42, -q.r * 0.34), q.dots)
    // Its arc shows only where it lies over a lump behind and under none in front: at most 66 degrees, open, centred
    // as near the upper left as the run allows.
    const pt = (a: number) =>
      `${n(q.cx + Math.cos(a) * q.r)} ${n(q.cy + Math.sin(a) * q.r)}`
    let run: number[] = []
    const flush = () => {
      if (run.length > 4) {
        const [lo, hi] = [run[1]!, run[run.length - 2]!]
        const mid = Math.min(Math.max(225 * DEG, lo + 33 * DEG), hi - 33 * DEG)
        const [a0, a1] = [
          Math.max(lo, mid - 33 * DEG),
          Math.min(hi, mid + 33 * DEG),
        ]
        arcs += `M ${pt(a0)} A ${n(q.r)} ${n(q.r)} 0 0 1 ${pt(a1)} `
      }
      run = []
    }
    for (let a = 150 * DEG; a <= 330 * DEG; a += 3 * DEG) {
      const [x, y] = [q.cx + Math.cos(a) * q.r, q.cy + Math.sin(a) * q.r]
      const behind = list.slice(0, i).some((b) => inside(b, x, y))
      if (behind && !list.slice(i + 1).some((f) => inside(f, x, y))) run.push(a)
      else flush()
    }
    flush()
  })
  const outline = `<path d="${d}" style="fill:var(--ink);stroke:var(--ink)" stroke-width="${p.L * 2}" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>`
  return outline + body + (arcs ? line(p, arcs) : "")
}

/**
 * A flat-bottomed cloud from x0 to x1 on `base`, rising to a crown: a front row in paper shaded with dots of the cloud
 * colour, and a back row in the cloud colour; or, given a coloured `face`, one row in that colour.
 */
export function puffCloud(
  p: Pen,
  r: Rs,
  [x0, x1, base, rmax]: number[],
  back = "cloud",
  face = "paper",
) {
  const solo = face !== "paper"
  const [ink, tone] = [stipple(p), dots(p, back)]
  const count =
    Math.max(3, Math.round((x1! - x0!) / (rmax! * 1.4))) + r.int(0, 1)
  const front = Array.from({ length: count }, (_, i) => {
    const t = i / (count - 1)
    const rad = rmax! * (0.62 + 0.38 * Math.sin(Math.PI * (0.15 + 0.7 * t)))
    const k = r.between(0.9, 1.05)
    return {
      ...puff(0, base! - rad * k, rad * k, face, solo ? ink : tone.url),
      t,
    }
  })
  const [first, last] = [front[0]!, front[count - 1]!]
  const span = x1! - x0! - first.r - last.r
  for (const q of front) q.cx = x0! + first.r + span * q.t
  const backs = Array.from({ length: solo ? 0 : count - 1 }, (_, i) => {
    const [a, b] = [front[i]!, front[i + 1]!]
    const rad = Math.max(a.r, b.r) * r.between(0.78, 0.92)
    const cy = Math.min(a.cy, b.cy) - rad * r.between(0.42, 0.6)
    return puff((a.cx + b.cx) / 2 + r.between(2, 10), cy, rad, back, ink)
  })
  const y0 = base! - Math.min(first.r, last.r)
  const floor = { x0: first.cx, x1: last.cx, y0, y1: base!, fill: face }
  return tone.def + lumps(p, [...backs, floor, ...front])
}

/** A constellation: five to seven stars, sparkles and pinpoints, joined by fine lines that stop short of each. */
const constellation: Draw = (p, r) => {
  // A walk of turning steps, scaled to fill the box, stretching one way by at most 1.8 times the other.
  const lay = r("layout")
  const count = lay.int(5, 7)
  let [x, y, head, bend] = [0, 0, lay.between(-0.5, 0.5), lay.pick([-1, 1])]
  const walk = Array.from({ length: count }, () => {
    const pt = { x, y }
    if (lay.chance(0.3)) bend = -bend
    head += bend * lay.between(0.3, 1.1)
    const len = lay.between(0.8, 1.3)
    ;[x, y] = [x + Math.cos(head) * len, y + Math.sin(head) * len]
    return pt
  })
  const [xs, ys] = [walk.map((q) => q.x), walk.map((q) => q.y)]
  const [x0, y0] = [Math.min(...xs), Math.min(...ys)]
  const span = Math.max(Math.max(...xs) - x0, 0.01)
  const tall = Math.max(Math.max(...ys) - y0, 0.01)
  const [kx, ky] = [240 / span, 164 / tall]
  const [sx, sy] = [Math.min(kx, ky * 1.8), Math.min(ky, kx * 1.8)]
  const [ox, oy] = [(300 - span * sx) / 2, (220 - tall * sy) / 2]
  const big = lay.int(0, count - 1)
  const kinds = r("kinds")
  const stars = walk.map((q, i) => {
    const spark = i === big || kinds.chance(0.5)
    const s = i === big ? kinds.between(21, 26) : kinds.between(10, 14)
    const kind = spark ? "spark" : kinds.chance(0.5) ? "ring" : "dot"
    return { x: ox + (q.x - x0) * sx, y: oy + (q.y - y0) * sy, kind, s }
  })
  const edges = stars.slice(1).map((_, i) => [i, i + 1] as [number, number])
  if (count >= 6 && lay.chance(0.6)) edges.push([count - 1, count - 4])
  else if (lay.chance(0.5))
    edges[lay.int(1, edges.length - 1)]![0] = lay.int(0, 1)
  const gapOf = (st: (typeof stars)[number]) =>
    st.kind === "spark" ? st.s * 0.5 + 5 : st.kind === "ring" ? 9 : 6
  let lines = ""
  for (const [a, b] of edges) {
    const [s0, s1] = [stars[a]!, stars[b]!]
    const d = Math.hypot(s1.x - s0.x, s1.y - s0.y) || 1
    const [ux, uy, g0, g1] = [
      (s1.x - s0.x) / d,
      (s1.y - s0.y) / d,
      gapOf(s0),
      gapOf(s1),
    ]
    if (d > g0 + g1 + 6)
      lines += `M ${n(s0.x + ux * g0)} ${n(s0.y + uy * g0)} L ${n(s1.x - ux * g1)} ${n(s1.y - uy * g1)} `
  }
  let out = lines ? looseLine(p, lines) : ""
  for (const st of stars)
    out +=
      st.kind === "spark"
        ? sparkle(p, st.x, st.y, st.s)
        : st.kind === "ring"
          ? ring(p, st.x, st.y, 4.2) + pinpoint(st.x, st.y, 1.4)
          : pinpoint(st.x, st.y, 2.6)
  const dust = r("dust")
  for (let i = 0; i < 4; i++)
    out += pinpoint(dust.between(20, 280), dust.between(20, 200), 1.3)
  return out
}

/** A rainbow: concentric bands in the ink line, each foot sunk into a cloud. */
const rainbow: Draw = (p, r, fills) => {
  const [cx, cy, R] = [160, 168, 144]
  const count = r("bands").int(4, 5)
  const bw = r("width").between(14, 17)
  const colours = ["sun", "plane-2", "highlight", "tone-4", "plane"]
  let bands = ""
  for (let i = 0; i < count; i++) {
    const [ro, ri, y] = [R - i * bw, R - (i + 1) * bw, cy + 8]
    const d =
      `M ${cx - ro} ${y} V ${cy} A ${ro} ${ro} 0 0 1 ${cx + ro} ${cy} V ${y} ` +
      `H ${cx + ri} V ${cy} A ${ri} ${ri} 0 0 0 ${cx - ri} ${cy} V ${y} Z`
    bands += shape(p, d, fillOf(fills, `band-${i}`, colours[i]!))
  }
  const [foot, half] = [R - (count * bw) / 2, (count * bw) / 2 + 20]
  const [s, cloud] = [r("sparkle"), fillOf(fills, "cloud", "cloud")]
  const left = [Math.max(4, cx - foot - half), cx - foot + half, 204, 32]
  const right = [cx + foot - half, Math.min(316, cx + foot + half), 204, 32]
  return (
    bands +
    sparkle(
      p,
      cx + s.between(-30, 30),
      cy - s.between(16, 34),
      s.between(9, 13),
    ) +
    puffCloud(p, r("left"), left, cloud) +
    puffCloud(p, r("right"), right, cloud)
  )
}

/** A towering cumulus: tiers of paper puffs narrowing to a crown, rising out of a bank in the cloud colour. */
const cumulus: Draw = (p, r, fills) => {
  const back = fillOf(fills, "cloud", "cloud")
  const tone = dots(p, back)
  const j = r("tiers")
  const lean = j.between(-8, 10)
  const tower: Lump[] = []
  // Tiers from the crown down, so the lower ones stand in front: count, centre height, spread, radius.
  for (const [count, cy, spread, rad] of [
    [1, 54, 0, 42],
    [2, 106, 26, 42],
    [3, 162, 46, 45],
    [3, 214, 60, 48],
  ] as const)
    for (let i = 0; i < count; i++) {
      const t = count === 1 ? 0 : (i / (count - 1)) * 2 - 1
      const x = 120 + lean * (1 - cy / 210) + t * spread + j.between(-5, 5)
      const rr = rad * j.between(0.88, 1.08)
      tower.push(puff(x, cy + j.between(-5, 5), rr, "paper", tone.url))
    }
  const dy = Math.max(0, 8 - Math.min(...tower.map((q) => q.cy - q.r)))
  for (const q of tower) q.cy += dy
  const bank = puffCloud(p, r("bank"), [6, 234, 294, 36], back, back)
  return tone.def + lumps(p, tower) + bank
}

/** A small floating cloud, flat-bottomed, in two tones: the cloud colour behind, paper in front. */
const cloudPuff: Draw = (p, r, fills) => {
  const size = [6, 194, 104, r("size").between(36, 40)]
  return puffCloud(p, r("puffs"), size, fillOf(fills, "cloud", "cloud"))
}

/** A star cluster: one bright star with a glint behind it, smaller sparkles round it, pinpoints and rings between. */
const starCluster: Draw = (p, r, fills) => {
  const lay = r("layout")
  const placed: { x: number; y: number; s: number }[] = []
  const place = (s: number, spread: number) => {
    for (let t = 0; t < 40; t++) {
      const x = 130 + (lay.next() + lay.next() - 1) * spread
      const y = 110 + (lay.next() + lay.next() - 1) * spread * 0.8
      if (x - s < 6 || x + s > 254 || y - s < 6 || y + s > 214) continue
      if (placed.some((q) => Math.hypot(q.x - x, q.y - y) < q.s + s + 6))
        continue
      placed.push({ x, y, s })
      return { x, y }
    }
    return null
  }
  const big = r("big").between(30, 36)
  const c = place(big, 40)!
  const tone = tintOf(fillOf(fills, "glint", "sun"), 80)
  const glint = star(p, c.x, c.y, big * 0.8, tone)
  let out = `<g transform="rotate(45 ${n(c.x)} ${n(c.y)})">${glint}</g>`
  out += star(p, c.x, c.y, big, "paper")
  const sizes = r("sizes")
  const colour = fillOf(fills, "star", "sun")
  const medium = sizes.int(3, 4)
  for (let i = 0; i < medium + sizes.int(3, 5); i++) {
    const s = i < medium ? sizes.between(12, 17) : sizes.between(6, 9)
    const q = place(s, i < medium ? 95 : 125)
    if (q)
      out += i === 1 ? star(p, q.x, q.y, s, colour) : sparkle(p, q.x, q.y, s)
  }
  for (let i = 0; i < 12; i++) {
    const q = place(3, i < 6 ? 80 : 130)
    if (q)
      out +=
        i % 4 ? pinpoint(q.x, q.y, 1.2 + (i % 3) * 0.5) : ring(p, q.x, q.y, 3.2)
  }
  return out
}

/** The moon's phases: five small moons waxing from a crescent to full, strung on a fine line. */
const moonPhases: Draw = (p, r, fills) => {
  const moon = fillOf(fills, "moon", r("moon").pick(["plane-2", "sun"]))
  const dark = shade(fillOf(fills, "dark", "tone-4"), 76)
  const [cy, R] = [60, r("size").between(25, 28)]
  let out = looseLine(p, `M 6 ${cy} H 354`)
  for (const [i, f] of [0.16, 0.38, 0.62, 0.84, 1].entries()) {
    const cx = 44 + i * 68
    const k = 1 - 2 * f
    const [top, foot] = [`${cx} ${n(cy - R)}`, `${cx} ${n(cy + R)}`]
    // The lit side: the right half-disc, closed by the terminator, an ellipse.
    const lit =
      f >= 1
        ? circle(cx, cy, R)
        : `M ${top} A ${n(R)} ${n(R)} 0 0 1 ${foot} A ${n(Math.abs(k) * R + 0.01)} ${n(R)} 0 0 ${k > 0 ? 0 : 1} ${top} Z`
    out +=
      tint(circle(cx, cy, R), dark) +
      tint(circle(cx, cy, R), stipple(p)) +
      shape(p, lit, moon) +
      shape(p, circle(cx, cy, R), "none")
  }
  return out
}

export const SKY_MORE: Thing[] = [
  sky("constellation", "a constellation", 300, 220, constellation),
  sky("rainbow", "a rainbow", 320, 210, rainbow),
  sky("cumulus", "a towering cumulus", 240, 300, cumulus),
  sky("cloud-puff", "a small cloud", 200, 110, cloudPuff),
  sky("star-cluster", "a star cluster", 260, 220, starCluster),
  sky("moon-phases", "the phases of the moon", 360, 120, moonPhases),
]

// Objects: the sky. Each object draws in its own box; see library.ts for the contract and architecture.ts for the bar.
// Sky objects float: they fill their box rather than stand on its foot. Loose marks (rings, dots, the lines between
// stars) take the surface's text colour, so they show on Night's dark canvas; filled shapes keep the ink line.
import { shade, tintOf } from "../buildings"
import { ball, circle, crescent, ellipse, line, pinpoint } from "../motifs"
import { ring, shape, sparkle, stipple, tint } from "../motifs"
import { n, type Pen } from "../svg"
import { fillOf, type Thing } from "./library"

export const TAU = Math.PI * 2
const DEG = Math.PI / 180

export type Draw = Thing["draw"]

/** A sky object: it floats, filling its box. */
export const sky = (
  name: string,
  title: string,
  w: number,
  h: number,
  draw: Draw,
) => ({ name, title, collection: "sky", w, h, draw }) satisfies Thing

/** A puff (a circle) or a block (the flat base under a row of puffs), with its fill and its shading's paint. */
export type Lump = {
  cx: number
  cy: number
  r: number
  fill: string
  dots: string
}
export type Block = {
  x0: number
  x1: number
  y0: number
  y1: number
  fill: string
}
type N = number
export const puff = (cx: N, cy: N, r: N, fill: string, dots: string): Lump => {
  return { cx, cy, r, fill, dots }
}

/** Stipple in a spot colour: cloud-coloured dots shade a paper cloud, as on the poster. */
export function dots(p: Pen, role: string, k = 2.6) {
  const id = p.uid("dots")
  const dot = (c: number) =>
    `<circle cx="${n(c)}" cy="${n(c)}" r="${n((0.55 * k) / 3)}" style="fill:var(--${role})"/>`
  return {
    def: `<pattern id="${id}" width="${k}" height="${k}" patternUnits="userSpaceOnUse">${dot(k / 4) + dot((3 * k) / 4)}</pattern>`,
    url: `url(#${id})`,
  }
}

/** The point at angle `a` and radius `r` round (cx, cy), as "x y". */
export const at = (cx: number, cy: number, r: number, a: number) =>
  `${n(cx + Math.cos(a) * r)} ${n(cy + Math.sin(a) * r)}`

/** A four-point concave star like `sparkle`, in any fill. */
export function star(p: Pen, x: number, y: number, s: number, fill: string) {
  const k = s * 0.13
  const d =
    `M ${n(x)} ${n(y - s)} Q ${n(x + k)} ${n(y - k)} ${n(x + s)} ${n(y)} Q ${n(x + k)} ${n(y + k)} ${n(x)} ${n(y + s)} ` +
    `Q ${n(x - k)} ${n(y + k)} ${n(x - s)} ${n(y)} Q ${n(x - k)} ${n(y - k)} ${n(x)} ${n(y - s)} Z`
  return shape(p, d, fill)
}

/** An open line loose in the sky, in the surface's text colour (ink, or paper on Night). */
export const looseLine = (p: Pen, d: string) =>
  line(p, d, { style: "fill:none;stroke:var(--text, var(--ink))" })

/** A clip path from `d`, and a wrapper that applies it. */
export function clipTo(p: Pen, d: string) {
  const id = p.uid("sky")
  return {
    def: `<clipPath id="${id}"><path d="${d}"/></clipPath>`,
    wrap: (s: string) => `<g clip-path="url(#${id})">${s}</g>`,
  }
}

/** A gig-poster sunburst: a disc in a ring of long folded rays and short pale ones, all in the ink line. */
const sunRays: Draw = (p, r, fills) => {
  const [c, R] = [140, r("disc").between(60, 68)]
  const count = r("count").pick([10, 12, 14])
  const [step, turn] = [TAU / count, r("turn").between(0, TAU / count)]
  const rays = fillOf(fills, "rays", "sun")
  const pale = fillOf(fills, "short", tintOf(rays, 55))
  const reach = R * r("reach").between(1.78, 1.95)
  const pt = (rad: number, a: number) => at(c, c, rad, a)
  let [short, long] = ["", ""]
  for (let i = 0; i < count; i++) {
    const a = turn + i * step
    const w = step * (i % 2 ? 0.5 : 0.55)
    const [b0, mid, b1] = [
      pt(R * 0.9, a - w),
      pt(R * 0.9, a),
      pt(R * 0.9, a + w),
    ]
    if (i % 2) {
      const tip = `${pt(R * 1.52, a - 0.02)} L ${pt(R * 1.52, a + 0.02)}`
      short += shape(p, `M ${b0} L ${tip} L ${b1} Z`, pale)
      continue
    }
    // A long ray folds along its spine: the half turned from the light is in shade, stippled.
    const tip = pt(reach, a)
    const half = [`M ${b0} L ${tip} L ${mid} Z`, `M ${mid} L ${tip} L ${b1} Z`]
    const dk = Math.cos(a) < Math.sin(a) ? 0 : 1
    for (const [k, d] of half.entries())
      long += shape(p, d, k === dk ? shade(rays) : rays)
    long += tint(half[dk]!, stipple(p))
  }
  let inner = ""
  for (let i = r("rings").int(1, 2); i > 0; i--)
    inner += shape(p, circle(c, c, R * (0.96 - i * 0.16)), "none")
  return short + long + ball(p, c, c, R, fillOf(fills, "disc", "sun")) + inner
}

/** A planet with a tilted ring: the ring's back half passes behind it, its front half over it, casting a shadow. */
const ringedPlanet: Draw = (p, r, fills) => {
  const [cx, cy, R] = [150, 112, r("size").between(56, 62)]
  const pick = r("planet").pick(["tone-3", "plane", "tone-4"])
  const body = fillOf(fills, "planet", pick)
  const band = fillOf(fills, "ring", "sun")
  const [k, tilt] = [r("open").between(0.24, 0.3), r("tilt").between(-20, -11)]
  const [ro, rm, ri] = [1.92, 1.6, 1.3].map((f) =>
    ellipse(cx, cy, R * f, R * f * k),
  )
  const odd = { "fill-rule": "evenodd" }
  const ringSvg =
    shape(p, `${ro} ${rm}`, band, odd) +
    shape(p, `${rm} ${ri}`, tintOf(band, 55), odd)
  const rot = (s: string) =>
    `<g transform="rotate(${n(tilt)} ${cx} ${cy})">${s}</g>`
  const disc = circle(cx, cy, R)
  const planet = clipTo(p, disc)
  const front = clipTo(p, `M 0 ${cy} H 300 V 220 H 0 Z`)
  // Two latitude bands curve like the ring, seen a little from above.
  const [x0, x1, bow] = [n(cx - R - 4), n(cx + R + 4), R * 0.3]
  const lat = (y0: number, y1: number) =>
    `M ${x0} ${n(y0)} Q ${cx} ${n(y0 + bow)} ${x1} ${n(y0)} V ${n(y1)} Q ${cx} ${n(y1 + bow)} ${x0} ${n(y1)} Z`
  const y0 = cy - R * r("bands").between(0.62, 0.72)
  const bands =
    tint(lat(y0, y0 + R * 0.2), tintOf(body, 55)) +
    tint(lat(y0 + R * 0.32, y0 + R * 0.42), shade(body, 90))
  // The front half's shadow falls on the planet just below it.
  const drop = { ...odd, transform: `translate(0 ${n(R * 0.16)})` }
  const cast = front.wrap(tint(`${ro} ${ri}`, stipple(p), drop))
  const dark = crescent(cx, cy, R, -R * 0.42, -R * 0.34)
  return (
    planet.def +
    front.def +
    rot(ringSvg) +
    tint(disc, body) +
    planet.wrap(rot(bands + cast)) +
    tint(dark, shade(body)) +
    tint(dark, stipple(p)) +
    shape(p, disc, "none") +
    rot(front.wrap(ringSvg))
  )
}

/** A fat crescent moon, stippled along its inner edge, with a sparkle in its bite. */
const crescentMoon: Draw = (p, r, fills) => {
  const [cx, cy, R] = [104, 122, r("size").between(84, 90)]
  const pick = r("moon").pick(["plane-2", "sun", "highlight"])
  const a = r("tilt").between(-0.5, -0.2)
  const bite = r("bite").between(0.56, 0.66) * R
  const [ox, oy] = [Math.cos(a) * bite, Math.sin(a) * bite]
  const d = crescent(cx, cy, R, ox, oy)
  const c = clipTo(p, d)
  const band = R * r("band").between(0.16, 0.22)
  const [sx, sy] = [cx + ox + R * 0.18, cy + oy - R * 0.02]
  return (
    c.def +
    shape(p, d, fillOf(fills, "moon", pick)) +
    c.wrap(tint(circle(cx + ox, cy + oy, R + band), stipple(p))) +
    shape(p, d, "none") +
    sparkle(p, sx, sy, r("sparkle").between(16, 21)) +
    ring(p, sx + R * 0.32, sy + R * 0.44, 3.6) +
    pinpoint(sx - R * 0.08, sy - R * 0.5, 1.8)
  )
}

/** A comet: a round head trailing tapering bands of spot colour that part as they go. */
const comet: Draw = (p, r, fills) => {
  const Rh = r("head").between(26, 30)
  const [hx, hy, tx, ty] = [326 - Rh, Rh + 14, 12, r("tail").between(150, 186)]
  const bend = r("bend").between(26, 40) / Math.hypot(hx - tx, hy - ty)
  const qx = (hx + tx) / 2 + (hy - ty) * bend
  const qy = (hy + ty) / 2 - (hx - tx) * bend
  const bez = (t: number, u = 1 - t) =>
    [
      u * u * hx + 2 * u * t * qx + t * t * tx,
      u * u * hy + 2 * u * t * qy + t * t * ty,
    ] as const
  const count = r("bands").int(3, 4)
  const colours = ["sun", "highlight", "plane", "tone-4"]
  const hw0 = (Rh * 1.05) / count
  let bands = ""
  for (let i = 0; i < count; i++) {
    const off = i - (count - 1) / 2
    const reach = 1 - Math.abs(off) * r(`len-${i}`).between(0.12, 0.22)
    const [left, right] = [[], []] as [string[], string[]]
    for (let s = 0; s <= 24; s++) {
      const t = (s / 24) * reach
      const [x, y] = bez(t)
      const [x2, y2] = bez(Math.min(t + 0.01, 1))
      const dl = Math.hypot(x2 - x, y2 - y) || 1
      const [nx, ny] = [-(y2 - y) / dl, (x2 - x) / dl]
      const o = off * 2 * hw0 * (1 + 1.6 * t)
      const hw = hw0 * (1 + 0.5 * t) * (1 - s / 24) ** 0.6
      left.push(`${n(x + nx * (o - hw))} ${n(y + ny * (o - hw))}`)
      right.unshift(`${n(x + nx * (o + hw))} ${n(y + ny * (o + hw))}`)
    }
    const fill = fillOf(fills, `band-${i}`, colours[i]!)
    bands += shape(p, `M ${left.join(" L ")} L ${right.join(" L ")} Z`, fill)
  }
  const g = Rh + 8
  const glow = `M ${at(hx, hy, g, -2.6)} A ${n(g)} ${n(g)} 0 0 1 ${at(hx, hy, g, 0.7)}`
  const [s, dot] = [r("spark"), r("dot")]
  return (
    bands +
    ball(p, hx, hy, Rh, fillOf(fills, "head", "paper")) +
    looseLine(p, glow) +
    sparkle(p, s.between(60, 140), s.between(26, 50), 10) +
    pinpoint(dot.between(200, 260), dot.between(150, 185), 1.8)
  )
}

/** A shooting star: a big sparkle leading a curved trail of rounded stripes, staggered at both ends. */
const shootingStar: Draw = (p, r, fills) => {
  // The trail falls along an arc round a centre low on the left, from the upper left down to the star.
  const [cx, cy, Rm, w] = [14, 404, 356, 12]
  const count = r("stripes").int(3, 4)
  const colours = ["sun", "plane-2", "highlight", "plane"]
  const pt = (rad: number, a: number) => at(cx, cy, rad, a)
  let stripes = ""
  for (let i = 0; i < count; i++) {
    const off = i - (count - 1) / 2
    const [ro, ri, c] = [Rm + off * 17 + w / 2, Rm + off * 17 - w / 2, w / 2]
    const a0 = (-52 - r(`head-${i}`).between(0, 3)) * DEG
    const a1 = (-87 + Math.abs(off) * r(`tail-${i}`).between(6, 11)) * DEG
    // An annular strip from the tail a1 to the head a0, round at both ends.
    const d =
      `M ${pt(ro, a1)} A ${n(ro)} ${n(ro)} 0 0 1 ${pt(ro, a0)} A ${c} ${c} 0 0 1 ${pt(ri, a0)} ` +
      `A ${n(ri)} ${n(ri)} 0 0 0 ${pt(ri, a1)} A ${c} ${c} 0 0 1 ${pt(ro, a1)} Z`
    stripes += shape(p, d, fillOf(fills, `stripe-${i}`, colours[i]!))
  }
  const [sx, sy] = [
    cx + Rm * Math.cos(-47 * DEG),
    cy + Rm * Math.sin(-47 * DEG),
  ]
  const s = r("size").between(34, 40)
  return (
    stripes +
    star(p, sx, sy, s, fillOf(fills, "star", "paper")) +
    sparkle(p, sx - 22, sy + 50, 9) +
    ring(p, sx - 150, sy + 8, 3.4) +
    pinpoint(sx - 120, sy + 46, 1.8)
  )
}

/** An eclipse: the moon's disc crossing the sun, a pale corona of fine rays, and a sparkle where the rims cross. */
const eclipse: Draw = (p, r, fills) => {
  const [c, R] = [130, 66]
  const sun = fillOf(fills, "sun", "sun")
  const count = r("rays").pick([28, 32, 36])
  const step = TAU / count
  const pt = (rad: number, a: number) => at(c, c, rad, a)
  let rays = ""
  for (let i = 0; i < count; i++) {
    const [a, odd] = [i * step, i % 2 === 1]
    const tip = pt(R * (odd ? 1.62 : 1.86), a)
    const d = `M ${pt(R * 1.2, a - step * 0.3)} L ${tip} L ${pt(R * 1.2, a + step * 0.3)} Z`
    rays += shape(p, d, odd ? tintOf(sun, 55) : sun)
  }
  const da = r("moon").between(-2.6, -1.9)
  const d = R * r("offset").between(0.24, 0.34)
  const [mx, my, mr] = [c + Math.cos(da) * d, c + Math.sin(da) * d, R * 1.02]
  // Where the rims cross: the diamond ring.
  const a = Math.acos((d * d + R * R - mr * mr) / (2 * d * R))
  const ra = da + r("ring").pick([-1, 1]) * a
  const [sx, sy] = [c + Math.cos(ra) * R, c + Math.sin(ra) * R]
  return (
    rays +
    shape(p, circle(c, c, R * 1.26), tintOf(sun, 45)) +
    ball(p, c, c, R, sun) +
    shape(p, circle(mx, my, mr), fillOf(fills, "moon", "ink")) +
    sparkle(p, sx, sy, r("size").between(16, 20))
  )
}

